import { tableSchemas } from "../data/datasets";

function levenshtein(a: string, b: string): number {
  const tmp: number[][] = [];
  for (let i = 0; i <= a.length; i++) {
    tmp[i] = [i];
  }
  for (let j = 0; j <= b.length; j++) {
    tmp[0][j] = j;
  }
  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      tmp[i][j] = Math.min(
        tmp[i - 1][j] + 1, // deletion
        tmp[i][j - 1] + 1, // insertion
        tmp[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1), // substitution
      );
    }
  }
  return tmp[a.length][b.length];
}

function findClosestTable(name: string): string | null {
  const tables = tableSchemas.map((t) => t.name);
  let bestMatch: string | null = null;
  let bestDist = 3; // threshold
  for (const t of tables) {
    const d = levenshtein(name.toLowerCase(), t.toLowerCase());
    if (d < bestDist) {
      bestDist = d;
      bestMatch = t;
    }
  }
  return bestMatch;
}

function findClosestColumn(colName: string): string | null {
  const cleanCol = colName.includes(".") ? colName.split(".")[1] : colName;
  const allColumns = Array.from(
    new Set(tableSchemas.flatMap((t) => t.columns.map((c) => c.name))),
  );

  let bestMatch: string | null = null;
  let bestDist = 3;
  for (const c of allColumns) {
    const d = levenshtein(cleanCol.toLowerCase(), c.toLowerCase());
    if (d < bestDist) {
      bestDist = d;
      bestMatch = c;
    }
  }
  return bestMatch;
}

export function translateSqlError(rawError: string, sql?: string): string {
  // Strip Error: prefix if exists
  const cleanRaw = rawError.replace(/^Error:\s*/i, "").trim();
  let lineNum = 1;

  function findLineNumber(token: string): number {
    if (!sql || !token) return 1;
    const cleanToken = token.replace(/['"]/g, "").trim();
    if (!cleanToken) return 1;
    const lines = sql.split("\n");
    const escaped = cleanToken.replace(/[-\/\\^$*+?.()|[\]{}]/g, "\\$&");
    const wordRegex = new RegExp("\\b" + escaped + "\\b", "i");
    for (let i = 0; i < lines.length; i++) {
      if (wordRegex.test(lines[i])) {
        return i + 1;
      }
    }
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].toLowerCase().includes(cleanToken.toLowerCase())) {
        return i + 1;
      }
    }
    return 1;
  }

  type TranslationDef = {
    pattern: RegExp;
    msgCode: number; // MySQL error code
    sqlState: string; // MySQL SQLSTATE
    getToken?: (m: RegExpMatchArray) => string;
    detailed: (m: RegExpMatchArray) => string;
    getSuggestion?: (m: RegExpMatchArray) => string | null;
  };

  const translations: TranslationDef[] = [
    {
      pattern: /misuse of window function/i,
      msgCode: 3593,
      sqlState: "HY000",
      detailed: () =>
        "Windowed functions (like ROW_NUMBER(), RANK(), OVER()) can only appear in the " +
        "SELECT or ORDER BY clauses. They cannot be used in the WHERE, GROUP BY, or HAVING " +
        "clauses.",
    },
    {
      pattern:
        /(nested.*window|context of another windowed function|aggregate function.*nested|window.*nested)/i,
      msgCode: 3593,
      sqlState: "HY000",
      detailed: () =>
        "Windowed functions cannot be used in the context of another windowed function or aggregate.",
    },
    {
      pattern: /misuse of aggregate/i,
      msgCode: 1111,
      sqlState: "HY000",
      detailed: () =>
        "Aggregate functions (like SUM, COUNT, MAX) cannot appear in the WHERE clause. " +
        "Use the HAVING clause instead to filter on aggregated results.",
    },
    {
      pattern: /no such column:\s*(['"]?[a-zA-Z0-9_\.]+['"]?)/i,
      msgCode: 1054,
      sqlState: "42S22",
      getToken: (m) => m[1],
      detailed: (m) =>
        `Unknown column '${m[1].replace(/['"]/g, "")}' in 'field list'. Please check your spelling ` +
        `or verify that the column exists in the referenced tables.`,
      getSuggestion: (m) => {
        const col = m[1].replace(/['"]/g, "");
        const match = findClosestColumn(col);
        return match ? `Did you mean column \`${match}\`?` : null;
      },
    },
    {
      pattern: /no such table:\s*(['"]?[a-zA-Z0-9_]+['"]?)/i,
      msgCode: 1146,
      sqlState: "42S02",
      getToken: (m) => m[1],
      detailed: (m) =>
        `Table '${m[1].replace(/['"]/g, "")}' doesn't exist in the database.`,
      getSuggestion: (m) => {
        const tbl = m[1].replace(/['"]/g, "");
        const match = findClosestTable(tbl);
        return match ? `Did you mean table \`${match}\`?` : null;
      },
    },
    {
      pattern: /ambiguous column name:\s*(['"]?[a-zA-Z0-9_]+['"]?)/i,
      msgCode: 1052,
      sqlState: "23000",
      getToken: (m) => m[1],
      detailed: (m) =>
        `Column '${m[1].replace(/['"]/g, "")}' in field list is ambiguous. Prefix it with ` +
        `the table name or alias (e.g., table_name.${m[1].replace(/['"]/g, "")}).`,
    },
    {
      pattern: /near (['"]?.*?['"]?):\s*syntax error/i,
      msgCode: 1064,
      sqlState: "42000",
      getToken: (m) => m[1],
      detailed: (m) =>
        `You have an error in your SQL syntax; check for correct syntax near ${m[1]}. ` +
        `Verify commas, unclosed parentheses, or misspelled keywords.`,
    },
    {
      pattern: /returns ([0-9]+) columns - expected ([0-9]+)/i,
      msgCode: 1241,
      sqlState: "21000",
      detailed: (m) =>
        `Operand should contain 1 column(s), but the subquery returns ${m[1]} columns.`,
    },
    {
      pattern: /([0-9]+) values for ([0-9]+) columns/i,
      msgCode: 1136,
      sqlState: "21S01",
      detailed: (m) =>
        `Column count doesn't match value count. You supplied ${m[1]} values but the target specifies ` +
        `${m[2]} columns.`,
    },
    {
      pattern: /division by zero/i,
      msgCode: 1365,
      sqlState: "22012",
      detailed: () =>
        "Division by zero error. Consider using NULLIF(denominator, 0) to prevent evaluation crashes.",
    },
    {
      pattern: /row value misused/i,
      msgCode: 1064,
      sqlState: "42000",
      detailed: () =>
        "Incorrect use of row value. Ensure aggregate functions or subqueries are referenced correctly inside conditional operators.",
    },
    {
      pattern:
        /(more than one row returned by a subquery|cardinality violation)/i,
      msgCode: 1242,
      sqlState: "21000",
      detailed: () =>
        "Subquery returns more than 1 row. This is not permitted with comparative operators (e.g., =, !=, <, >). Use IN instead, or add LIMIT 1.",
    },
    {
      pattern: /UNIQUE constraint failed/i,
      msgCode: 1062,
      sqlState: "23000",
      detailed: () =>
        "Duplicate entry for key. The value violates a unique key or primary key constraint.",
    },
    {
      pattern: /FOREIGN KEY constraint failed/i,
      msgCode: 1452,
      sqlState: "23000",
      detailed: () =>
        "Cannot add or update child row: a foreign key constraint fails. The referenced parent ID does not exist.",
    },
    {
      pattern: /NOT NULL constraint failed:\s*(['"]?[a-zA-Z0-9_\.]+['"]?)/i,
      msgCode: 1048,
      sqlState: "23000",
      getToken: (m) => m[1],
      detailed: (m) =>
        `Column '${m[1].replace(/['"]/g, "")}' cannot be null. Please provide a valid non-null value.`,
    },
    {
      pattern: /ORDER BY term out of range - should be between 1 and (\d+)/i,
      msgCode: 1064,
      sqlState: "42000",
      detailed: (m) =>
        `Unknown column index in ORDER BY. The SELECT list only contains ${m[1]} columns.`,
    },
    {
      pattern:
        /(use of non-aggregate column|aggregated query without GROUP BY)/i,
      msgCode: 1055,
      sqlState: "42000",
      detailed: () =>
        "Expression in SELECT list is not in GROUP BY clause and contains nonaggregated column. Aggregate rules require selecting only grouped columns or columns inside aggregates.",
    },
    {
      pattern: new RegExp(
        "SELECTs to the left and right of (?:UNION|EXCEPT|INTERSECT) " +
          "do not have the same number of result columns",
        "i",
      ),
      msgCode: 1222,
      sqlState: "21000",
      detailed: () =>
        "The used SELECT statements have a different number of columns. Both sides of UNION must contain the same number of fields.",
    },
    {
      pattern: /table (['"]?[a-zA-Z0-9_]+['"]?) already exists/i,
      msgCode: 1050,
      sqlState: "42S01",
      getToken: (m) => m[1],
      detailed: (m) =>
        `Table '${m[1].replace(/['"]/g, "")}' already exists. Use 'DROP TABLE IF EXISTS' first.`,
    },
    {
      pattern: /view (['"]?[a-zA-Z0-9_]+['"]?) already exists/i,
      msgCode: 1050,
      sqlState: "42S01",
      getToken: (m) => m[1],
      detailed: (m) =>
        `View '${m[1].replace(/['"]/g, "")}' already exists. Use 'DROP VIEW IF EXISTS' first.`,
    },
    {
      pattern: /index (['"]?[a-zA-Z0-9_]+['"]?) already exists/i,
      msgCode: 1061,
      sqlState: "42000",
      getToken: (m) => m[1],
      detailed: (m) =>
        `Duplicate key name '${m[1].replace(/['"]/g, "")}'. An index with this name already exists.`,
    },
    {
      pattern: /table (['"]?[a-zA-Z0-9_]+['"]?) has more than one primary key/i,
      msgCode: 1075,
      sqlState: "42000",
      getToken: (m) => m[1],
      detailed: (m) =>
        `Multiple primary key defined for table '${m[1].replace(/['"]/g, "")}'.`,
    },
    {
      pattern: /duplicate column name:\s*(['"]?[a-zA-Z0-9_]+['"]?)/i,
      msgCode: 1060,
      sqlState: "42S21",
      getToken: (m) => m[1],
      detailed: (m) =>
        `Duplicate column name '${m[1].replace(/['"]/g, "")}' in table definition.`,
    },
    {
      pattern: /cannot modify (['"]?[a-zA-Z0-9_]+['"]?) because it is a view/i,
      msgCode: 1015,
      sqlState: "HY000",
      getToken: (m) => m[1],
      detailed: (m) =>
        `Cannot modify view '${m[1].replace(/['"]/g, "")}'. Read-only target.`,
    },
    {
      pattern: /cannot start a transaction within a transaction/i,
      msgCode: 1305,
      sqlState: "25000",
      detailed: () =>
        "Active transaction exists. Commit or Rollback the current transaction first.",
    },
    {
      pattern:
        /cannot commit - no transaction active|cannot rollback - no transaction active/i,
      msgCode: 1305,
      sqlState: "25000",
      detailed: () =>
        "No active transaction exists. Run BEGIN before committing or rolling back.",
    },
    {
      pattern: /temporary table name must be unqualified/i,
      msgCode: 1064,
      sqlState: "42000",
      detailed: () =>
        "Temporary table names cannot be qualified with schema names.",
    },
  ];

  for (const t of translations) {
    const match = cleanRaw.match(t.pattern);
    if (match) {
      if (t.getToken) {
        lineNum = findLineNumber(t.getToken(match));
      } else {
        if (cleanRaw.includes("window")) lineNum = findLineNumber("OVER");
        else if (cleanRaw.includes("aggregate"))
          lineNum = findLineNumber("WHERE");
      }

      const detailedMsg = t.detailed(match);
      const sugg = t.getSuggestion ? t.getSuggestion(match) : null;
      const suggStr = sugg ? `\nSuggestion: ${sugg}` : "";
      return `ERROR ${t.msgCode} (${t.sqlState}) at line ${lineNum}\n${detailedMsg}${suggStr}`;
    }
  }

  // Generic fallback if not matched
  return (
    `ERROR 1064 (42000) at line 1\n` +
    `Database Error: ${cleanRaw}\n\n` +
    `Please review your SQL syntax and logic.`
  );
}

export interface LintError {
  id: string;
  severity: "warning" | "error" | "info";
  message: string;
  line: number;
  column: number;
  length: number;
  fixText?: string;
  suggestion: string;
}

function maskStringLiterals(text: string): string {
  let result = "";
  let inSingleQuote = false;
  let inDoubleQuote = false;
  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    if (char === "'" && !inDoubleQuote) {
      inSingleQuote = !inSingleQuote;
      result += "'";
    } else if (char === '"' && !inSingleQuote) {
      inDoubleQuote = !inDoubleQuote;
      result += '"';
    } else {
      if (inSingleQuote || inDoubleQuote) {
        result += " ";
      } else {
        result += char;
      }
    }
  }
  return result;
}

function maskParentheses(text: string): string {
  let result = "";
  let depth = 0;
  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    if (char === "(") {
      depth++;
      result += "(";
    } else if (char === ")") {
      depth = Math.max(0, depth - 1);
      result += ")";
    } else {
      result += depth > 0 ? " " : char;
    }
  }
  return result;
}

function splitColumnsByOuterCommas(text: string): string[] {
  const result: string[] = [];
  let current = "";
  let depth = 0;
  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    if (char === "(") {
      depth++;
      current += char;
    } else if (char === ")") {
      depth = Math.max(0, depth - 1);
      current += char;
    } else if (char === "," && depth === 0) {
      result.push(current.trim());
      current = "";
    } else {
      current += char;
    }
  }
  if (current.trim()) {
    result.push(current.trim());
  }
  return result;
}

function getNormalizedColumn(expr: string): string {
  let clean = expr.split(/\bAS\b/i)[0].trim();
  if (clean.includes(" ") && !clean.includes("(") && !clean.includes(")")) {
    const parts = clean.split(/\s+/);
    if (parts.length > 1) {
      const last = parts[parts.length - 1];
      if (/^[a-zA-Z0-9_]+$/.test(last)) {
        clean = parts.slice(0, -1).join(" ").trim();
      }
    }
  }
  return clean.toLowerCase();
}

export function lintSqlQuery(sql: string): LintError[] {
  const errors: LintError[] = [];
  if (!sql.trim()) return errors;

  const maskedStringSql = maskStringLiterals(sql);
  const maskedSql = maskParentheses(maskedStringSql);

  // Rule 1: Catch SELECT * in query
  const selectAllRegex = /\bSELECT\s+(\*)(?=\s|,|$)/gi;
  let match;
  while ((match = selectAllRegex.exec(maskedStringSql)) !== null) {
    const offset = match.index;
    const { line, col } = getLineAndColFromOffset(
      sql,
      offset + match[0].indexOf("*"),
    );
    errors.push({
      id: "select_all",
      severity: "warning",
      message: "Avoid using SELECT * in production or analytical queries.",
      line,
      column: col,
      length: 1,
      suggestion:
        "Explicitly name the columns you require. This improves execution performance and" +
        "makes the query robust to schema modifications.",
    });
  }

  // Rule 2: Aggregate function in WHERE clause
  const aggWhereRegex =
    /\bWHERE\s+(?:(?!\bSELECT\b)[\s\S])*?\b(COUNT|SUM|AVG|MIN|MAX)\s*\(/gi;
  while ((match = aggWhereRegex.exec(maskedStringSql)) !== null) {
    const offset = match.index;
    const { line, col } = getLineAndColFromOffset(sql, offset);
    errors.push({
      id: "aggregate_where",
      severity: "error",
      message: `Aggregate function ${match[1]}() is not allowed in WHERE.`,
      line,
      column: col,
      length: match[0].length,
      suggestion:
        "Filter raw rows in WHERE. To filter grouped aggregates, place the condition inside a" +
        "HAVING clause after GROUP BY.",
    });
  }

  // Rule 3: Text string double quote verification
  const doubleQuoteStringRegex =
    /\b(WHERE|JOIN|AND|OR)\s+[a-zA-Z0-9_.]+\s*=\s*("[^"\n]*")/gi;
  while ((match = doubleQuoteStringRegex.exec(maskedStringSql)) !== null) {
    const valString = match[2];
    const offset = match.index + match[0].indexOf(valString);
    const { line, col } = getLineAndColFromOffset(sql, offset);
    errors.push({
      id: "double_quote_string",
      severity: "info",
      message: "Double quotes used for string literal values.",
      line,
      column: col,
      length: valString.length,
      fixText: valString.replace(/"/g, "'"),
      suggestion:
        "In SQL, single quotes denote text literals (e.g. 'Mumbai'). Double quotes are" +
        "reserved for column/table identifiers with spaces or special characters.",
    });
  }

  // Rule 4: Leading wildcard in LIKE (Performance issue)
  const leadingWildcardRegex = /\bLIKE\s+(['"]%[^'"]+['"])/gi;
  while ((match = leadingWildcardRegex.exec(maskedStringSql)) !== null) {
    const literal = match[1];
    const offset = match.index;
    const { line, col } = getLineAndColFromOffset(sql, offset);
    errors.push({
      id: "leading_wildcard",
      severity: "warning",
      message: "Leading wildcard in LIKE clause disables index structures.",
      line,
      column: col,
      length: match[0].length,
      suggestion:
        "Beginning a search term with '%' (e.g. '%Mumbai') forces a full table scan. If" +
        "possible, use trailing wildcards ('Mumbai%') or full-text indexing.",
    });
  }

  // Rule 5: GROUP BY missing non-aggregate columns
  const hasAgg = /\b(COUNT|SUM|AVG|MIN|MAX)\b\(/i.test(maskedStringSql);
  const hasGroupBy = /\bGROUP\s+BY\b/i.test(maskedStringSql);

  if (hasAgg && !hasGroupBy) {
    // If standard fields and aggregates are mixed in SELECT without GROUP BY
    const selectFields = maskedStringSql.match(
      /\bSELECT\s+([\s\S]*?)\bFROM\b/i,
    );
    if (selectFields) {
      const fields = splitColumnsByOuterCommas(selectFields[1]);
      const hasNonAgg = fields.some((f) => {
        const trimmedField = f.trim();
        return (
          !/(COUNT|SUM|AVG|MIN|MAX)\(/i.test(trimmedField) &&
          trimmedField !== "*" &&
          !/^(NULL|\d+(\.\d+)?|'[^']*'|"[^"]*")$/i.test(trimmedField)
        );
      });
      if (hasNonAgg) {
        errors.push({
          id: "missing_group_by",
          severity: "error",
          message:
            "Mixed scalar and aggregate columns in SELECT with no GROUP BY clause.",
          line: 1,
          column: 1,
          length: 6,
          suggestion:
            "Add a GROUP BY clause specifying all columns in the SELECT that are not" +
            "wrapped in aggregate functions.",
        });
      }
    }
  }

  // Rule 11: SELECT columns not in GROUP BY clause when GROUP BY is present
  if (hasGroupBy) {
    const selectMatch = maskedStringSql.match(/\bSELECT\s+([\s\S]*?)\bFROM\b/i);
    const groupByMatch = maskedStringSql.match(
      /\bGROUP\s+BY\s+([\s\S]*?)(?:\bHAVING\b|\bORDER\s+BY\b|\bLIMIT\b|$)/i,
    );
    if (selectMatch && groupByMatch) {
      const selectFields = splitColumnsByOuterCommas(selectMatch[1]);
      const groupByFields = splitColumnsByOuterCommas(groupByMatch[1]).map(
        (f) => getNormalizedColumn(f),
      );

      // Bypass if using positional grouping (e.g. GROUP BY 1, 2)
      const hasPositionalGroupBy = groupByFields.some((f) => /^\d+$/.test(f));

      if (!hasPositionalGroupBy) {
        selectFields.forEach((field) => {
          const trimmed = field.trim();
          const isAggregate = /(COUNT|SUM|AVG|MIN|MAX)\b\(/i.test(
            maskStringLiterals(trimmed),
          );
          if (isAggregate) return;

          if (/^(NULL|\d+|'[^']*'|"[^"]*")$/i.test(trimmed)) return;

          const normSelect = getNormalizedColumn(trimmed);
          if (!normSelect) return;

          const selectBase = normSelect.includes(".")
            ? normSelect.split(".")[1]
            : normSelect;
          const isGrouped = groupByFields.some((g) => {
            const gBase = g.includes(".") ? g.split(".")[1] : g;
            return g === normSelect || gBase === selectBase;
          });

          if (!isGrouped) {
            const offset = maskedStringSql.indexOf(trimmed);
            const { line, col } = getLineAndColFromOffset(
              sql,
              offset !== -1 ? offset : 0,
            );
            errors.push({
              id: "unaggregated_column_missing_group_by",
              severity: "error",
              message: `Column '${trimmed}' must appear in the GROUP BY clause or be used in an aggregate function.`,
              line,
              column: col,
              length: trimmed.length,
              suggestion:
                "In standard SQL, any non-aggregated column in the SELECT list must be" +
                "included in the GROUP BY clause. Add this column to your GROUP BY list or" +
                "wrap it in an aggregate function (like MAX or MIN) if appropriate.",
            });
          }
        });
      }
    }
  }

  // Rule 6: HAVING clause without GROUP BY
  const hasHaving = /\bHAVING\b/i.test(maskedStringSql);
  if (hasHaving && !hasGroupBy) {
    const matchHaving = maskedStringSql.match(/\bHAVING\b/i);
    const offset = matchHaving ? matchHaving.index || 0 : 0;
    const { line, col } = getLineAndColFromOffset(sql, offset);
    errors.push({
      id: "having_without_group_by",
      severity: "error",
      message: "HAVING clause used without a GROUP BY clause.",
      line,
      column: col,
      length: 6,
      suggestion:
        "A HAVING clause filters aggregated groups. It requires a GROUP BY clause to define" +
        "those groups. If you want to filter raw rows, use WHERE instead.",
    });
  }

  // Rule 7: Non-aggregate condition in HAVING
  const havingRegex =
    /\bHAVING\s+([\s\S]*?)(?:\bGROUP\s+BY\b|\bORDER\s+BY\b|\bLIMIT\b|$)/i;
  const havingMatch = maskedSql.match(havingRegex);
  if (havingMatch) {
    const havingClause = havingMatch[1];
    const havingIndex = havingMatch.index || 0;
    const conditions = havingClause.split(/\b(?:AND|OR)\b/i);
    for (const cond of conditions) {
      const trimmedCond = cond.trim();
      if (trimmedCond && !/(COUNT|SUM|AVG|MIN|MAX)\b/i.test(trimmedCond)) {
        const offset = sql.indexOf(trimmedCond, havingIndex);
        if (offset !== -1) {
          const { line, col } = getLineAndColFromOffset(sql, offset);
          errors.push({
            id: "non_aggregate_having",
            severity: "warning",
            message:
              "Non-aggregate condition placed in HAVING instead of WHERE.",
            line,
            column: col,
            length: trimmedCond.length,
            suggestion:
              "Filtering non-aggregate columns in HAVING runs after the database" +
              "performs grouping. Move this filter to the WHERE clause to discard rows" +
              "early, which dramatically speeds up the query.",
          });
        }
      }
    }
  }

  // Rule 8: NOT IN used with subquery
  const notInSubqueryRegex = /\bNOT\s+IN\s*\(\s*SELECT\b/gi;
  while ((match = notInSubqueryRegex.exec(maskedStringSql)) !== null) {
    const offset = match.index;
    const { line, col } = getLineAndColFromOffset(sql, offset);
    errors.push({
      id: "not_in_nullable_subquery",
      severity: "warning",
      message: "NOT IN used with a subquery — risk of NULL trap.",
      line,
      column: col,
      length: match[0].length,
      suggestion:
        "If the subquery returns even a single NULL, NOT IN will evaluate to UNKNOWN and" +
        "return zero rows. Consider using NOT EXISTS or ensuring the subquery filters out" +
        "NULLs (e.g., WHERE col IS NOT NULL).",
    });
  }

  // Rule 9: Comma Join (implicit join) syntax
  const implicitJoinRegex =
    /\bFROM\s+[a-zA-Z0-9_]+(?:\s+(?:AS\s+)?[a-zA-Z0-9_]+)?\s*,\s*[a-zA-Z0-9_]+/gi;
  while ((match = implicitJoinRegex.exec(maskedSql)) !== null) {
    const offset = match.index;
    const { line, col } = getLineAndColFromOffset(sql, offset);
    errors.push({
      id: "implicit_join_comma",
      severity: "warning",
      message: "Implicit join syntax (comma-separated tables) used.",
      line,
      column: col,
      length: match[0].length,
      suggestion:
        "Use explicit JOIN syntax (e.g. INNER JOIN ... ON ...) instead of comma joins." +
        "Explicit joins are easier to read, prevent accidental Cartesian products, and make" +
        "join conditions clear.",
    });
  }

  // Rule 10: JOIN without ON/USING
  const joinRegex = new RegExp(
    "\\bJOIN\\s+([a-zA-Z0-9_]+)(?:\\s+AS\\s+)?\\s*" +
      "(?!ON\\b|USING\\b)([a-zA-Z0-9_]+)?\\s*([\\s\\S]*?)" +
      "(?=\\bJOIN\\b|\\bWHERE\\b|\\bGROUP\\b|\\bORDER\\b|\\bLIMIT\\b|$)",
    "gi",
  );
  while ((match = joinRegex.exec(maskedSql)) !== null) {
    const clauseBody = match[3];
    if (!/\bON\b|\bUSING\b/i.test(clauseBody)) {
      const offset = match.index;
      const { line, col } = getLineAndColFromOffset(sql, offset);
      errors.push({
        id: "missing_join_on",
        severity: "error",
        message: `JOIN clause for '${match[1]}' is missing an ON join condition.`,
        line,
        column: col,
        length: Math.max(1, match[0].length - clauseBody.length),
        suggestion:
          "Specify an ON clause (e.g., JOIN orders ON customers.id = orders.customer_id) to" +
          "define how the tables relate. Otherwise, the database cannot resolve the join.",
      });
    }
  }

  // Rule 11: UPDATE/DELETE without WHERE clause (Unbounded Mutation Warning)
  const mutationNoWhereRegex =
    /\b(UPDATE\s+[a-zA-Z0-9_]+|DELETE\s+FROM\s+[a-zA-Z0-9_]+)\s*(?![\s\S]*?\bWHERE\b)[\s\S]*?$/gi;
  while ((match = mutationNoWhereRegex.exec(maskedSql)) !== null) {
    if (!/\bWHERE\b/i.test(maskedSql)) {
      const offset = match.index;
      const { line, col } = getLineAndColFromOffset(sql, offset);
      errors.push({
        id: "unbounded_mutation_no_where",
        severity: "warning",
        message:
          "UPDATE or DELETE statement without a WHERE clause will affect ALL rows in the table.",
        line,
        column: col,
        length: match[1].length,
        suggestion:
          "Add a WHERE clause (e.g., WHERE id = 10) to target specific rows and avoid accidentally modifying or deleting the entire dataset.",
      });
    }
  }

  // Rule 12: Deeply Nested Subquery Complexity (Recommend CTE)
  const nestedSubqueryRegex =
    /\(\s*SELECT[\s\S]*?\(\s*SELECT[\s\S]*?\(\s*SELECT/gi;
  while ((match = nestedSubqueryRegex.exec(maskedSql)) !== null) {
    const offset = match.index;
    const { line, col } = getLineAndColFromOffset(sql, offset);
    errors.push({
      id: "deeply_nested_subquery_use_cte",
      severity: "info",
      message: "Deeply nested subqueries detected (3+ levels deep).",
      line,
      column: col,
      length: match[0].length,
      suggestion:
        "Refactor deeply nested subqueries into Common Table Expressions (CTEs using WITH) to improve query readability and modularity.",
    });
  }

  return errors;
}

function getLineAndColFromOffset(text: string, offset: number) {
  const prefix = text.substring(0, offset);
  const lines = prefix.split("\n");
  return {
    line: lines.length,
    col: lines[lines.length - 1].length + 1,
  };
}

import initSqlJs from "sql.js";
import sqlWasmUrl from "sql.js/dist/sql-wasm.wasm?url";
import {
  registerMySqlFunctions,
  prepareMySqlForSqlite,
} from "../utils/mysqlCompat";
import { seedDatabaseInstance } from "../utils/dbSeeder";

let SQL: initSqlJs.SqlJsStatic | null = null;
let dbInstance: initSqlJs.Database | null = null;

function hasSandboxTransactionControl(sql: string): boolean {
  const transactionCommands = new Set([
    "COMMIT",
    "ROLLBACK",
    "BEGIN",
    "SAVEPOINT",
    "RELEASE",
  ]);
  const tokenPattern =
    /'(?:''|[^'])*'|"(?:""|[^"])*"|`[^`]*`|--[^\r\n]*|\/\*[\s\S]*?\*\/|;|[A-Za-z_][A-Za-z0-9_]*/g;
  let statementStart = true;
  let match: RegExpExecArray | null;

  while ((match = tokenPattern.exec(sql)) !== null) {
    const token = match[0];
    if (token === ";") {
      statementStart = true;
      continue;
    }
    if (
      token.startsWith("'") ||
      token.startsWith('"') ||
      token.startsWith("`") ||
      token.startsWith("--") ||
      token.startsWith("/*")
    ) {
      continue;
    }
    if (statementStart && transactionCommands.has(token.toUpperCase())) {
      return true;
    }
    statementStart = false;
  }
  return false;
}

export interface WorkerMessageData {
  id: string;
  type:
    | "INIT"
    | "EXECUTE"
    | "RESET"
    | "GET_SCHEMA"
    | "GET_PLAN"
    | "CANCEL"
    | "EXPORT"
    | "IMPORT_CSV";
  sql?: string;
  snapshot?: ArrayBuffer;
  sandbox?: boolean;
  takeSnapshot?: boolean;
  csvData?: { tableName: string; ddl: string; insertStatements: string[] };
}

self.onmessage = async (e: MessageEvent<WorkerMessageData>) => {
  const {
    id,
    type,
    sql = "",
    snapshot,
    sandbox = false,
    takeSnapshot = false,
    csvData,
  } = e.data;

  if (type === "CANCEL") {
    if (dbInstance) {
      try {
        dbInstance.run("ROLLBACK;");
      } catch (_) {}
    }
    self.postMessage({
      id,
      status: "SUCCESS",
      message: "Worker operation cancelled",
    });
    return;
  }

  if (type === "INIT") {
    try {
      if (!SQL) {
        SQL = await initSqlJs({
          locateFile: () => sqlWasmUrl,
        });
      }
      if (dbInstance) {
        try {
          dbInstance.close();
        } catch (_) {}
      }
      dbInstance = new SQL.Database(
        snapshot ? new Uint8Array(snapshot) : undefined,
      );
      registerMySqlFunctions(dbInstance);
      dbInstance.run("PRAGMA foreign_keys = ON;");
      dbInstance.run("PRAGMA synchronous = OFF;");
      dbInstance.run("PRAGMA journal_mode = MEMORY;");
      dbInstance.run("PRAGMA temp_store = MEMORY;");
      if (!snapshot) {
        seedDatabaseInstance(dbInstance);
      }
      self.postMessage({ id, status: "READY" });
    } catch (err: unknown) {
      self.postMessage({ id, status: "ERROR", error: String(err) });
    }
    return;
  }

  if (type === "RESET") {
    try {
      if (!SQL) {
        SQL = await initSqlJs({
          locateFile: () => sqlWasmUrl,
        });
      }
      if (dbInstance) {
        try {
          dbInstance.close();
        } catch (_) {}
      }
      dbInstance = new SQL.Database();
      registerMySqlFunctions(dbInstance);
      dbInstance.run("PRAGMA foreign_keys = ON;");
      dbInstance.run("PRAGMA synchronous = OFF;");
      dbInstance.run("PRAGMA journal_mode = MEMORY;");
      dbInstance.run("PRAGMA temp_store = MEMORY;");
      seedDatabaseInstance(dbInstance);
      self.postMessage({ id, status: "READY" });
    } catch (err: unknown) {
      self.postMessage({ id, status: "ERROR", error: String(err) });
    }
    return;
  }

  if (type === "EXPORT") {
    if (!dbInstance) {
      self.postMessage({
        id,
        status: "ERROR",
        error: "Database not initialized",
      });
      return;
    }
    try {
      const binary = dbInstance.export();
      (
        self as unknown as {
          postMessage: (msg: unknown, transfer?: Transferable[]) => void;
        }
      ).postMessage({ id, status: "SUCCESS", snapshot: binary.buffer }, [
        binary.buffer,
      ]);
    } catch (err: unknown) {
      self.postMessage({ id, status: "ERROR", error: String(err) });
    }
    return;
  }

  if (type === "GET_SCHEMA") {
    if (!dbInstance) {
      self.postMessage({ id, status: "SUCCESS", result: [] });
      return;
    }
    try {
      const tablesRes = dbInstance.exec(
        "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'",
      );
      const schemas: Array<{
        name: string;
        columns: Array<{ name: string; type: string }>;
        count: number;
      }> = [];

      if (tablesRes && tablesRes.length > 0) {
        const tableNames = tablesRes[0].values.map(
          (r: unknown[]) => r[0] as string,
        );
        for (const t of tableNames) {
          const infoRes = dbInstance.exec(`PRAGMA table_info([${t}])`);
          const countRes = dbInstance.exec(`SELECT COUNT(*) FROM [${t}]`);
          const columns =
            infoRes[0]?.values.map((r: unknown[]) => ({
              name: r[1] as string,
              type: (r[2] as string) || "TEXT",
            })) || [];
          const count = Number(countRes[0]?.values[0]?.[0] || 0);
          schemas.push({ name: t, columns, count });
        }
      }
      self.postMessage({ id, status: "SUCCESS", result: schemas });
    } catch (err: unknown) {
      self.postMessage({ id, status: "ERROR", error: String(err) });
    }
    return;
  }

  if (type === "GET_PLAN") {
    if (!dbInstance || !sql.trim()) {
      self.postMessage({ id, status: "SUCCESS", result: [] });
      return;
    }
    try {
      const sqlToRun = prepareMySqlForSqlite(sql);
      const planRes = dbInstance.exec(`EXPLAIN QUERY PLAN ${sqlToRun}`);
      const steps: Array<{ id: number; parent: number; detail: string }> = [];
      if (planRes && planRes.length > 0) {
        for (const row of planRes[0].values) {
          steps.push({
            id: Number(row[0]),
            parent: Number(row[1]),
            detail: String(row[3]),
          });
        }
      }
      self.postMessage({ id, status: "SUCCESS", result: steps });
    } catch (err: unknown) {
      self.postMessage({ id, status: "SUCCESS", result: [] });
    }
    return;
  }

  if (type === "IMPORT_CSV") {
    if (!dbInstance || !csvData) {
      self.postMessage({
        id,
        status: "ERROR",
        error: "Missing database or CSV data",
      });
      return;
    }
    try {
      dbInstance.run("BEGIN TRANSACTION;");
      dbInstance.run(csvData.ddl);
      let insertedRows = 0;
      for (const stmt of csvData.insertStatements) {
        dbInstance.run(stmt);
        insertedRows++;
      }
      dbInstance.run("COMMIT;");
      self.postMessage({
        id,
        status: "SUCCESS",
        result: {
          message: `Successfully imported table [${csvData.tableName}] with ${insertedRows} batch operations.`,
        },
      });
    } catch (err: unknown) {
      try {
        dbInstance.run("ROLLBACK;");
      } catch (_) {}
      self.postMessage({
        id,
        status: "ERROR",
        error: `CSV Import failed: ${String(err)}`,
      });
    }
    return;
  }

  if (type === "EXECUTE") {
    if (!dbInstance) {
      self.postMessage({
        id,
        status: "ERROR",
        error: "Worker database not initialized",
      });
      return;
    }

    const savepointName = `sb_${Date.now()}_${Math.floor(Math.random() * 10000)}`;
    let savepointActive = false;

    const t0 = performance.now();
    try {
      if (sandbox && hasSandboxTransactionControl(sql)) {
        throw new Error(
          "Transaction-control statements are not allowed in sandbox mode.",
        );
      }
      if (sandbox) {
        dbInstance.run(`SAVEPOINT ${savepointName};`);
        savepointActive = true;
      }

      const sqlToRun = prepareMySqlForSqlite(sql);
      const res = dbInstance.exec(sqlToRun);
      const durationMs = Math.round(performance.now() - t0);

      let columns: string[] = [];
      let rowObjects: Record<string, unknown>[] = [];

      if (res && res.length > 0) {
        const lastResult = res[res.length - 1];
        columns = lastResult.columns;
        const MAX_ROWS = 250;
        const rawValues = lastResult.values;
        const cappedValues =
          rawValues.length > MAX_ROWS
            ? rawValues.slice(0, MAX_ROWS)
            : rawValues;

        rowObjects = cappedValues.map((rowArr: unknown[]) => {
          const obj: Record<string, unknown> = {};
          columns.forEach((col, idx) => {
            let val = rowArr[idx];
            if (typeof val === "string" && val.length > 250) {
              val = val.substring(0, 250) + "... [Truncated]";
            }
            obj[col] = val;
          });
          return obj;
        });
      }

      let snapshotData: Record<string, unknown[]> | null = null;
      if (takeSnapshot) {
        snapshotData = {};
        const tablesRes = dbInstance.exec(
          "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'",
        );
        if (tablesRes && tablesRes.length > 0) {
          for (const r of tablesRes[0].values) {
            const tableName = r[0] as string;
            const rowsRes = dbInstance.exec(`SELECT * FROM [${tableName}]`);
            snapshotData[tableName] =
              rowsRes && rowsRes.length > 0 ? rowsRes[0].values : [];
          }
        }
      }

      if (savepointActive) {
        try {
          dbInstance.run(`ROLLBACK TO ${savepointName};`);
          dbInstance.run(`RELEASE ${savepointName};`);
        } catch (_) {
          // If user query issued explicit COMMIT/ROLLBACK, SQLite released savepoint automatically
          try {
            dbInstance.run("ROLLBACK;");
          } catch (_) {}
        }
      }

      try {
        dbInstance.run("PRAGMA shrink_memory;");
      } catch (_) {}

      self.postMessage({
        id,
        status: "SUCCESS",
        result: {
          columns,
          rows: rowObjects,
          message: `Query executed successfully (${rowObjects.length} row${rowObjects.length !== 1 ? "s" : ""})`,
          durationMs,
          snapshot: snapshotData,
        },
      });
    } catch (err: unknown) {
      if (savepointActive) {
        try {
          dbInstance.run(`ROLLBACK TO ${savepointName};`);
          dbInstance.run(`RELEASE ${savepointName};`);
        } catch (_) {
          try {
            dbInstance.run("ROLLBACK;");
          } catch (_) {}
        }
      }
      self.postMessage({
        id,
        status: "ERROR",
        error:
          (err as Error)?.message || String(err) || "Query execution failed",
      });
    }
  }
};

