          if (backup.drafts && typeof backup.drafts === "object") {
            setStorageItem(
              "sql-aa-problem-drafts",
              JSON.stringify(backup.drafts),
            );
          }
          if (backup.puzzleDrafts && typeof backup.puzzleDrafts === "object") {
