    });

    // Bind Ctrl+Z to Undo in Monaco Editor
    editor.addAction({
      id: "undo-action-ctrl-z",
      label: "Undo (Ctrl+Z)",
      keybindings: [monaco.KeyMod.CtrlCmd | monaco.KeyCode.KeyZ],
      run: (ed) => {
        ed.trigger("keyboard", "undo", null);
      },
