            style={{ display: "flex", gap: "10px", justifyContent: "flex-end" }}
          >
            <button
              className="primary-button outline compact"
              onClick={() => setCustomPromptOpen(false)}
            >
              Cancel
            </button>
            <button
              className="primary-button compact"
              onClick={() => {
                if (customPromptOnSubmit)
                  customPromptOnSubmit(customPromptValue);
                setCustomPromptOpen(false);
              }}
              style={{
                background: "var(--violet)",
                borderColor: "var(--violet)",
              }}
            >
              Submit
            </button>
          </div>
        </div>
      </div>
    );
  }

  // ROADMAP DAY DETAILS VIEW

  /* SHELL */

  return (
    <div className={`app-shell ${sidebarOpen ? "sb-open" : "sb-closed"}`}>
      {sidebarOpen && (
        <>
          <div
            className="sidebar-backdrop"
            onClick={() => setSidebarOpen(false)}
          />
          {/* ── SIDEBAR ───────────────────────────────────── */}
          <aside className="sidebar">
            <div
              className="brand-row"
              style={{
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                width: "100%",
              }}
            >
              <div
                style={{ display: "flex", alignItems: "center", gap: "10px" }}
              >
                <div
                  className="brand-mark"
                  style={{
                    background: "rgba(56, 217, 255, 0.12)",
                    border: "1px solid rgba(56, 217, 255, 0.3)",
                    borderRadius: "8px",
                    width: "32px",
                    height: "32px",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    color: "var(--cyan)",
                  }}
                >
                  <Database size={17} />
                </div>
                <div>
                  <strong>SQL</strong>
                  <span>Academy</span>
                </div>
              </div>
              <button
                className="icon-button sidebar-toggle-btn"
                onClick={() => setSidebarOpen((o) => !o)}
                title="Toggle Sidebar"
                aria-label="Toggle Sidebar"
                style={{
                  background: "transparent",
                  border: "none",
                  color: "var(--text-secondary)",
                  cursor: "pointer",
                  padding: "6px",
                  borderRadius: "6px",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                <Menu size={18} />
              </button>
            </div>

            <nav
              className="sidebar-nav"
              role="tablist"
              aria-label="Main Navigation"
