                      <strong>{item.label}</strong>
                    </button>
                  ))}
                </div>
              )}
            </div>
          </div>

          <div className="topbar-right">
            <div style={{ position: "relative", display: "inline-block" }}>
              <button
                className={`icon-button theme-toggle-btn ${theme} ${themeMenuOpen ? "active" : ""}`}
                onClick={() => setThemeMenuOpen(!themeMenuOpen)}
                title={`Theme: ${theme}. Click to select theme.`}
                aria-label="Select visual theme"
              >
                {theme === "dark" && (
                  <Moon size={16} style={{ color: "#38bdf8" }} />
                )}
                {theme === "light" && (
                  <Sun size={16} style={{ color: "#0284c7" }} />
                )}
                {theme === "oled" && (
                  <Zap size={16} style={{ color: "#a855f7" }} />
                )}
                {theme === "dracula" && (
                  <Palette size={16} style={{ color: "#ff79c6" }} />
                )}
                {theme === "onedark" && (
                  <Code2 size={16} style={{ color: "#61afef" }} />
                )}
                {theme === "ember" && (
                  <Flame size={16} style={{ color: "#f97316" }} />
                )}
              </button>

              {themeMenuOpen && (
                <>
                  <div
                    style={{ position: "fixed", inset: 0, zIndex: 9998 }}
                    onClick={() => setThemeMenuOpen(false)}
                  />
                  <div className="theme-popover">
                    <div
                      style={{
                        padding: "6px 8px 8px 8px",
                        borderBottom: "1px solid var(--border)",
                        display: "flex",
                        justifyContent: "space-between",
                        alignItems: "center",
                      }}
                    >
                      <span
                        style={{
                          fontSize: "11px",
                          fontWeight: "700",
                          textTransform: "uppercase",
                          letterSpacing: "0.5px",
                          color: "var(--muted)",
                        }}
                      >
                        Color Themes
                      </span>
                      <button
                        onClick={cycleTheme}
                        style={{
                          background: "none",
                          border: "none",
                          color: "var(--cyan)",
