                      >
                        <div
                          style={{
                            display: "flex",
                            alignItems: "center",
                            gap: "10px",
                          }}
                        >
                          <span
                            style={{ color: opt.color, display: "inline-flex" }}
                          >
                            {opt.id === "dark" && <Moon size={14} />}
                            {opt.id === "light" && <Sun size={14} />}
                            {opt.id === "oled" && <Zap size={14} />}
                            {opt.id === "dracula" && <Palette size={14} />}
                            {opt.id === "onedark" && <Code2 size={14} />}
                            {opt.id === "ember" && <Flame size={14} />}
