          }`}
          style={{
            flex: 1,
            overflow: "auto",
            position: "relative",
          }}
          id="main-scroll-container"
        >
          <Suspense
            fallback={
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  height: "100%",
                  width: "100%",
                  flexDirection: "column",
                  gap: "1rem",
