                setSqlUpperKeywords={setSqlUpperKeywords}
                editorFontSize={editorFontSize}
                setEditorFontSize={setEditorFontSize}
                editorWordWrap={editorWordWrap}
                setEditorWordWrap={setEditorWordWrap}
                editorMinimap={editorMinimap}
                setEditorMinimap={setEditorMinimap}
                editorFontFamily={editorFontFamily}
                setEditorFontFamily={setEditorFontFamily}
                editorTabSize={editorTabSize}
                setEditorTabSize={setEditorTabSize}
                editorTheme={editorTheme}
                setEditorTheme={setEditorTheme}
                theme={theme}
                setTheme={setTheme}
                rightOpen={rightOpen}
                setRightOpen={setRightOpen}
                query={query}
                setQuery={setQuery}
                queryResult={queryResult}
                setQueryResult={setQueryResult}
                expectedResult={expectedResult}
                setExpectedResult={setExpectedResult}
                graderFeedback={graderFeedback}
                setGraderFeedback={setGraderFeedback}
                runCurrentQuery={runCurrentQuery}
                copyToClipboard={copyToClipboard}
                openInPlayground={openInPlayground}
                markProblemSolved={markProblemSolved}
                handleRightNavKeyDown={handleRightNavKeyDown}
                classForDiff={classForDiff}
                editorRef={editorRef}
                queryRef={queryRef}
                handleBeforeMount={handleBeforeMount}
                handleMount={handleMount}
                handleEditorChange={handleEditorChange}
                dbReady={dbReady}
                streak={streak}
                showToast={showToast}
                liveSchema={liveSchema}
                setLiveSchema={setLiveSchema}
                savedQueries={savedQueries}
                setSavedQueries={setSavedQueries}
                showConfirm={showConfirm}
                showPrompt={showPrompt}
                graderStrict={graderStrict}
                setGraderStrict={setGraderStrict}
                activePuzzle={activePuzzle}
                setActivePuzzleId={setActivePuzzleId}
                debugPuzzles={debugPuzzles}
                getSavedPuzzleQuery={getSavedPuzzleQuery}
                getSavedDraftQuery={getSavedDraftQuery}
                updateEditorQuery={updateEditorQuery}
                stopAutoTyping={stopAutoTyping}
                allProblems={allProblems}
                monacoRef={monacoRef}
                insertTextAtCursor={insertTextAtCursor}
                lintErrors={lintErrors}
                isAutoTyping={isAutoTyping}
                autoTypeQuery={autoTypeQuery}
                queryHistory={queryHistory}
                setQueryHistory={setQueryHistory}
                setSelectedDayId={setSelectedDayId}
                setActiveView={setActiveView}
                learningRoadmap={learningRoadmap}
                readiness={readiness}
                totalModules={totalModules}
                totalProblems={totalProblems}
              />
            )}
            {activeView === "puzzles" && (
              <PuzzlesView
                progress={progress}
                debugPuzzles={debugPuzzles}
                activePuzzle={activePuzzle}
                setActivePuzzleId={setActivePuzzleId}
                openPuzzleInPlayground={openPuzzleInPlayground}
                markPuzzleSolved={markPuzzleSolved}
                updateEditorQuery={updateEditorQuery}
                setActiveView={setActiveView}
                setPlaygroundMode={setPlaygroundMode}
                classForDiff={classForDiff}
              />
            )}
            {(activeView === "mocks" ||
              activeView === "mock-runner" ||
              activeView === "mock-results") && (
              <MockTestView
                activeView={activeView}
                setActiveView={setActiveView}
                progress={progress}
                mockInterviews={mockInterviews}
                mockHistory={mockHistory}
                interviewQuestionBank={interviewQuestionBank}
                mockTest={mockTest}
                setMockTest={setMockTest}
                mockReviewIndex={mockReviewIndex}
                setMockReviewIndex={setMockReviewIndex}
                startMockTest={startMockTest}
                submitMockAnswer={submitMockAnswer}
                runCurrentQuery={runCurrentQuery}
                queryRef={queryRef}
                queryResult={queryResult}
                resultPage={resultPage}
                setResultPage={setResultPage}
                RESULT_PAGE_SIZE={15}
                updateEditorQuery={updateEditorQuery}
                editorTheme={editorTheme}
                theme={theme}
                query={query}
                handleBeforeMount={handleBeforeMount}
                handleMount={handleMount}
                handleEditorChange={handleEditorChange}
                editorMinimap={editorMinimap}
                editorFontSize={editorFontSize}
                editorFontFamily={editorFontFamily}
                editorTabSize={editorTabSize}
                editorWordWrap={editorWordWrap}
              />
            )}
            {activeView === "day-details" && (
              <DayDetailsView
                selectedDayId={selectedDayId}
                progress={progress}
                learningRoadmap={learningRoadmap}
                roadmapModules={roadmapModules}
                debugPuzzles={debugPuzzles}
                setActiveView={setActiveView}
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                setSelectedDayId={setSelectedDayId}
                toggleDayComplete={toggleDayComplete}
                toggleChecklistItem={toggleChecklistItem}
                selectModule={selectModule}
                openInPlayground={openInPlayground}
                markProblemSolved={markProblemSolved}
                markPuzzleSolved={markPuzzleSolved}
                setActivePuzzleId={setActivePuzzleId}
                setPlaygroundMode={setPlaygroundMode}
                getSavedPuzzleQuery={getSavedPuzzleQuery}
                updateEditorQuery={updateEditorQuery}
                stopAutoTyping={stopAutoTyping}
                setQueryResult={setQueryResult}
                setExpectedResult={setExpectedResult}
              />
            )}
            {activeView === "missions" && (
              <MissionCapstoneView
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                onOpenStepInPlayground={(sql: any) => {
                  updateEditorQuery(sql, "free");
                  setActiveView("playground");
                }}
                onBackToRoadmap={() => setActiveView("roadmap")}
              />
            )}
            {activeView === "join-visualizer" && (
              <div
                style={{
                  padding: "2rem 3rem",
                  maxWidth: "900px",
                  margin: "0 auto",
                  width: "100%",
                }}
              >
                <ErrorBoundary fallbackTitle="SQL Join Venn Sandbox Panel">
                  <SqlJoinVennDiagram />
                </ErrorBoundary>
              </div>
            )}
          </Suspense>
        </div>
      </main>

      {showOnboarding && (
        <OnboardingModal
          roadmapLength={learningRoadmap.length}
          onClose={completeOnboarding}
        />
      )}
      {showShortcuts && (
        <ShortcutsModal onClose={() => setShowShortcuts(false)} />
      )}
      {activeColumnProfile && (
        <ColumnProfileModal
          profile={activeColumnProfile}
          onClose={() => setActiveColumnProfile(null)}
        />
      )}
      {customConfirmOpen && renderCustomConfirmModal()}
      {customPromptOpen && renderCustomPromptModal()}
      {toast && (
        <div
          style={{
            position: "fixed",
            bottom: "24px",
            right: "24px",
            zIndex: 9999,
            background:
              toast.type === "error"
                ? "rgba(239, 68, 68, 0.95)"
                : toast.type === "success"
                  ? "rgba(16, 185, 129, 0.95)"
                  : "rgba(31, 41, 55, 0.95)",
            color: "#fff",
            padding: "12px 24px",
            borderRadius: "8px",
            boxShadow: "0 10px 15px -3px rgba(0, 0, 0, 0.5)",
            display: "flex",
            alignItems: "center",
            gap: "8px",
            fontSize: "13px",
            fontWeight: 500,
            border:
              toast.type === "error"
                ? "1px solid rgba(239, 68, 68, 0.5)"
                : toast.type === "success"
                  ? "1px solid rgba(16, 185, 129, 0.5)"
                  : "1px solid rgba(255, 255, 255, 0.1)",
            backdropFilter: "blur(8px)",
            animation: "slideIn 0.2s ease-out forwards",
          }}
        >
          {toast.type === "success" && <CheckCircle2 size={16} />}
          {toast.type === "error" && <AlertTriangle size={16} />}
          {toast.type === "info" && <Lightbulb size={16} />}
          <span>{toast.message}</span>
        </div>
      )}
    </div>
  );
}

/* SUB-COMPONENTS */
function MetricCard({
  icon: Icon,
  label,
  value,
  accent,
  subtext,
  onClick,
}: {
  icon: LucideIcon;
  label: string;
  value: string;
  accent: string;
  subtext?: string;
  onClick?: () => void;
}) {
  return (
    <article
      className={`metric-card ${accent} ${onClick ? "interactive" : ""}`}
      onClick={onClick}
    >
      <div className="metric-icon">
        <Icon size={19} />
      </div>
      <span className="metric-lbl">{label}</span>
      <strong>{value}</strong>
      {subtext && <span className="metric-sub">{subtext}</span>}
    </article>
  );
}

function SectionTitle({
  icon: Icon,
  title,
  action,
}: {
  icon: LucideIcon;
  title: string;
  action?: string;
}) {
  return (
    <div className="section-title">
      <div>
        <Icon size={17} />
        <h2>{title}</h2>
      </div>
      {action && <span>{action}</span>}
    </div>
  );
}

function BulletList({ items }: { items: string[] }) {
  return (
    <ul className="bullet-list">
      {items.map((item, i) => (
        <li key={i}>{item}</li>
      ))}
    </ul>
  );
}

function QACard({
  q,
  a,
  followUp,
  mistake,
  onTry,
}: {
  q: string;
  a: string;
  followUp?: string;
  mistake?: string;
  onTry?: (sql: string) => void;
}) {
  const [open, setOpen] = useState(false);
  const sqlMatch =
    a.match(/```sql([\s\S]*?)```/) || a.match(/```([\s\S]*?)```/);
  const tryQuery = sqlMatch ? sqlMatch[1].trim() : null;

  return (
    <div className="qa-card">
      <button className="qa-question" onClick={() => setOpen((o) => !o)}>
        <span>{q}</span>
        <ChevronRight size={14} className={open ? "rotated" : ""} />
      </button>
      {open && (
        <div
          className="qa-answer"
          style={{ display: "flex", flexDirection: "column", gap: "8px" }}
        >
          <p style={{ whiteSpace: "pre-wrap" }}>{a}</p>
          {followUp && (
            <p className="qa-followup">
              <strong>Follow-up:</strong> {followUp}
            </p>
          )}
          {mistake && (
            <p className="qa-mistake">
              <strong>Common mistake:</strong> {mistake}
            </p>
          )}
        </div>
      )}
    </div>
  );
}

/* LESSON PROSE RENDERER 
   Turns raw text content into readable, styled prose.
   Detects bullets, SQL code blocks, headings, and paragraphs. */
const SQL_KEYWORDS =
  /^\s*(SELECT|FROM|WHERE|GROUP BY|ORDER BY|HAVING|JOIN|LEFT|INNER|WITH|INSERT|UPDATE|DELETE|CREATE|DROP|EXPLAIN|--)/i;
const BULLET_PREFIXES = /^\s*[-•✓✗→▸*]\s+/;
const HEADING_RE = /^[A-Z][A-Z0-9 _/:&-]{3,}:?\s*$|^[A-Z].{0,60}:$/;

function LessonProse({ text }: { text: string }) {
  const lines = text.split("\n");
  const elements: JSX.Element[] = [];
  let codeBuffer: string[] = [];
  let paraBuffer: string[] = [];

  function flushCode() {
    if (codeBuffer.length === 0) return;
    elements.push(
      <pre key={`code-${elements.length}`} className="lp-code">
        {codeBuffer.join("\n")}
      </pre>,
    );
    codeBuffer = [];
  }

  function flushPara() {
    if (paraBuffer.length === 0) return;
    const joined = paraBuffer.join(" ").trim();
    if (joined) {
      elements.push(<p key={`para-${elements.length}`}>{joined}</p>);
    }
    paraBuffer = [];
  }

  for (let i = 0; i < lines.length; i++) {
    const raw = lines[i];
    const trimmed = raw.trim();

    // blank line
    if (!trimmed) {
      flushCode();
      flushPara();
      continue;
    }

    // SQL code line
    if (SQL_KEYWORDS.test(trimmed) || trimmed.startsWith("`")) {
      flushPara();
      codeBuffer.push(raw.trimStart());
      continue;
    }

    // flush code if we're no longer in a SQL block
    flushCode();

    // bullet line
    if (BULLET_PREFIXES.test(raw)) {
      flushPara();
      const content = trimmed.replace(BULLET_PREFIXES, "");
      // Bold the part before first colon if any
      const colonIdx = content.indexOf(":");
      if (colonIdx > 0 && colonIdx < 50) {
        const label = content.slice(0, colonIdx);
        const rest = content.slice(colonIdx + 1);
        elements.push(
          <div key={`b-${elements.length}`} className="lp-bullet">
            <span>
              <strong>{label}</strong>
              {rest}
            </span>
          </div>,
        );
      } else {
        elements.push(
          <div key={`b-${elements.length}`} className="lp-bullet">
            {content}
          </div>,
        );
      }
      continue;
    }

    // heading-like line (short, all caps or ends with colon)
    if (HEADING_RE.test(trimmed) && trimmed.length < 80) {
      flushPara();
      elements.push(
        <div key={`h-${elements.length}`} className="lp-heading">
          {trimmed.replace(/:$/, "")}
        </div>,
      );
      continue;
    }

    // regular prose — accumulate into paragraph
    paraBuffer.push(trimmed);
  }

  flushCode();
  flushPara();

  return <div className="lesson-prose">{elements}</div>;
}

function QueryList({
  title,
  items,
  onLoad,
}: {
  title: string;
  items: QueryHistoryItem[];
  onLoad: (item: QueryHistoryItem) => void;
}) {
  return (
    <div className="query-list">
      <div className="query-list-head">
        <strong>{title}</strong>
        <span>{items.length}</span>
      </div>
      <div className="query-list-body">
        {items.length === 0 && <p>No queries yet.</p>}
        {items.slice(0, 5).map((item) => (
          <button key={item.id} onClick={() => onLoad(item)}>
            <span className={item.status}>{item.status}</span>
            <code>
              {item.query
                .split("\n")
                .find((l) => l.trim() && !l.trim().startsWith("--"))
                ?.trim()
                .slice(0, 60)}
            </code>
            <small>{fmtTime(item.createdAt)}</small>
          </button>
        ))}
      </div>
    </div>
  );
}

/* SPLIT PANE 
   Drag the divider between left and right to resize. */
function SplitPane({
  left,
  right,
  leftWidth,
  onResize,
  minLeft = 180,
  maxLeft = 700,
}: {
  left: React.ReactNode;
  right: React.ReactNode;
  leftWidth: number;
  onResize: (w: number) => void;
  minLeft?: number;
  maxLeft?: number;
}) {
  const containerRef = useRef<HTMLDivElement>(null);
  const dragging = useRef(false);

  function onMouseDown(e: React.MouseEvent) {
    e.preventDefault();
    dragging.current = true;
    document.body.style.cursor = "col-resize";
    document.body.style.userSelect = "none";

    const style = document.createElement("style");
    style.id = "h-split-drag-pointer-events-override";
    style.innerHTML =
      "* { pointer-events: none !important; } .split-handle, .split-handle * { pointer-events: auto !important; }";
    document.head.appendChild(style);

    function onMove(ev: MouseEvent) {
      if (!dragging.current || !containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const newW = Math.min(maxLeft, Math.max(minLeft, ev.clientX - rect.left));
      onResize(newW);
    }

    let safetyTimeout: ReturnType<typeof setTimeout> | null = setTimeout(
      onUp,
      3000,
    );

    function onUp() {
      if (safetyTimeout) {
        clearTimeout(safetyTimeout);
        safetyTimeout = null;
      }
      dragging.current = false;
      document.body.style.cursor = "";
      document.body.style.userSelect = "";
      const s = document.getElementById("h-split-drag-pointer-events-override");
      if (s) s.remove();
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mouseup", onUp);
    }

    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseup", onUp);
  }

  return (
    <div className="split-pane" ref={containerRef}>
      <div
        className="split-left"
        style={{ width: leftWidth, minWidth: leftWidth }}
      >
        {left}
      </div>
      <div
        className="split-handle"
        onMouseDown={onMouseDown}
        title="Drag to resize"
      >
        <div className="split-handle-bar" />
      </div>
      <div className="split-right">{right}</div>
    </div>
  );
}

function VSplitPane({
  top,
  bottom,
  topHeight,
  onResize,
  minTop = 100,
  maxTop = 1200,
  maximized = false,
}: {
  top: React.ReactNode;
  bottom: React.ReactNode;
  topHeight: number;
  onResize: (h: number) => void;
  minTop?: number;
  maxTop?: number;
  maximized?: boolean;
}) {
  const containerRef = useRef<HTMLDivElement>(null);
  const dragging = useRef(false);

  function onMouseDown(e: React.MouseEvent) {
    if (maximized) return;
    e.preventDefault();
    dragging.current = true;
    document.body.style.cursor = "row-resize";
    document.body.style.userSelect = "none";

    const style = document.createElement("style");
    style.id = "v-split-drag-pointer-events-override";
    style.innerHTML =
      "* { pointer-events: none !important; } .v-split-handle, .v-split-handle * { pointer-events: auto !important; }";
    document.head.appendChild(style);

    function onMove(ev: MouseEvent) {
      if (!dragging.current || !containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const newH = Math.min(maxTop, Math.max(minTop, ev.clientY - rect.top));
      onResize(newH);
    }

    let safetyTimeout: ReturnType<typeof setTimeout> | null = setTimeout(
      onUp,
      3000,
    );

    function onUp() {
      if (safetyTimeout) {
        clearTimeout(safetyTimeout);
        safetyTimeout = null;
      }
      dragging.current = false;
      document.body.style.cursor = "";
      document.body.style.userSelect = "";
      const s = document.getElementById("v-split-drag-pointer-events-override");
      if (s) s.remove();
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mouseup", onUp);
    }

    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseup", onUp);
  }

  return (
    <div
      className="v-split-pane"
      ref={containerRef}
      style={{
        display: "flex",
        flexDirection: "column",
        height: "100%",
        flex: 1,
        minHeight: 0,
      }}
    >
      <div
        className="v-split-top"
        style={{
          height: maximized ? "100%" : topHeight,
          minHeight: maximized ? "100%" : topHeight,
          overflow: "hidden",
          display: "flex",
          flexDirection: "column",
          flex: maximized ? 1 : "unset",
        }}
      >
        {top}
      </div>
      {!maximized && (
        <>
          <div
            className="v-split-handle"
            onMouseDown={onMouseDown}
            title="Drag to resize"
            style={{
              height: "6px",
              cursor: "row-resize",
              background: "transparent",
              flexShrink: 0,
              position: "relative",
              zIndex: 10,
              margin: "-3px 0",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <div
              className="v-split-handle-bar"
              style={{
                width: "40px",
                height: "4px",
                background: "var(--border)",
                borderRadius: "2px",
                transition: "background 0.2s",
              }}
            />
          </div>
          <div
            className="v-split-bottom"
            style={{
              flex: 1,
              minHeight: 0,
              overflow: "hidden",
              display: "flex",
              flexDirection: "column",
            }}
          >
            {bottom}
          </div>
        </>
      )}
    </div>
  );
}

import React, { useState } from "react";
import { Database, X, Minus, Plus, Zap } from "lucide-react";
import type { TableSchema } from "../data/datasets";

interface ErdModalViewProps {
  setErdModalOpen: (open: boolean) => void;
  liveSchema: TableSchema[];
  tableSchemas: TableSchema[];
}

export default function ErdModalView({
  setErdModalOpen,
  liveSchema,
  tableSchemas,
}: ErdModalViewProps) {
  // Scoped local states pushed down from App
  const [selectedTable, setSelectedTable] = useState<string | null>(null);
  const [hoveredTable, setHoveredTable] = useState<string | null>(null);
  const [erdZoom, setErdZoom] = useState(1);

  React.useEffect(() => {
    const modalElement = document.getElementById("erd-explorer-dialog");
    if (!modalElement) return;

    const focusable = modalElement.querySelectorAll(
      'button, select, [tabindex="0"]',
    );
    if (focusable.length > 0) {
      (focusable[0] as HTMLElement).focus();
    }

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        setErdModalOpen(false);
      }
      if (e.key === "Tab" && focusable.length > 0) {
        const first = focusable[0] as HTMLElement;
        const last = focusable[focusable.length - 1] as HTMLElement;
        if (e.shiftKey) {
          if (document.activeElement === first) {
            last.focus();
            e.preventDefault();
          }
        } else {
          if (document.activeElement === last) {
            first.focus();
            e.preventDefault();
          }
        }
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [setErdModalOpen]);

  const activeTable = selectedTable || hoveredTable;
  const liveTables = liveSchema.length > 0 ? liveSchema : tableSchemas;

  const liveTablesWithDefaults = liveTables.map((t) => ({
    ...t,
    domain:
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      (t as any).domain ||
      (t.name.toLowerCase().startsWith("temp")
        ? "Temporary Data"
        : "Custom Data"),
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    description:
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      (t as any).description ||
      (t.name.toLowerCase().startsWith("temp")
        ? "Temporary table generated during session execution."
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        : "Permanent database table created by user query."),
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    primaryKey:
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      (t as any).primaryKey || (t.columns[0] ? t.columns[0].name : ""),
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    relationships: (t as any).relationships || [],
  }));

  const activeSchema = liveTablesWithDefaults.find(
    (t) => t.name === activeTable,
  );
  const CORE_TABLES = [
    "customers",
    "orders",
    "order_items",
    "products",
    "subscriptions",
    "departments",
    "employees",
    "payments",
  ];
  const extraTables = liveTablesWithDefaults.filter(
    (t) => !CORE_TABLES.includes(t.name.toLowerCase()),
  );
  const canvasWidth = extraTables.length > 0 ? 920 : 730;

  const handleErdNodeKeyDown = (
    e: React.KeyboardEvent<SVGElement>,
    tableName: string,
  ) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      setSelectedTable(selectedTable === tableName ? null : tableName);
    }
  };

  const isConnected = (tableName: string) => {
    if (!activeTable) return false;
    if (tableName === activeTable) return true;
    const tableObj = liveTablesWithDefaults.find((t) => t.name === activeTable);
    if (tableObj) {
      const forward = tableObj.relationships.some((rel: string) => {
        const parts = rel.split(".");
        return parts[0] === tableName;
      });
      if (forward) return true;
    }

    const targetTableObj = liveTablesWithDefaults.find(
      (t) => t.name === tableName,
    );
    if (targetTableObj) {
      const reverse = targetTableObj.relationships.some((rel: string) => {
        const parts = rel.split(".");
        return parts[0] === activeTable;
      });
      if (reverse) return true;
    }

    return false;
  };

  const isPathHighlighted = (fromTable: string, toTable: string) => {
    if (!activeTable) return false;
    return (
      (fromTable === activeTable && isConnected(toTable)) ||
      (toTable === activeTable && isConnected(fromTable))
    );
  };

  const getAccentColor = (domain: string) => {
    switch (domain) {
      case "E-Commerce":
        return "var(--erd-customer-accent)";
      case "Sales":
        return "var(--erd-order-accent)";
      case "Retention":
        return "var(--erd-order-accent)";
      case "Product Performance":
