              </h2>
              <p
                style={{ fontSize: "10.5px", color: "var(--muted)", margin: 0 }}
              >
                Hover to highlight joins, click to select and lock schema
                properties
              </p>
            </div>
          </div>
          <button
            className="icon-button"
            onClick={() => setErdModalOpen(false)}
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
            aria-label="Close ERD Explorer"
          >
            <X size={16} />
