                    ? "1px solid var(--success)"
                    : "1px solid var(--error)",
                }}
              >
                <h4
                  style={{
                    margin: "0 0 8px 0",
                    color: gradeMsg.isCorrect
                      ? "var(--success)"
                      : "var(--error)",
