                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            ) : (
              <div
                style={{ color: "var(--text-muted)", fontFamily: "monospace" }}
              >
                {result?.message || "Run a query to see results..."}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

