                  width: "40px",
                  height: "40px",
                  border: "1px solid rgba(249, 115, 22, 0.25)",
                }}
              >
                🔥
              </div>
              <div>
                <span
                  style={{
                    display: "block",
                    fontSize: "11px",
                    color: "var(--muted)",
                    textTransform: "uppercase",
                    fontWeight: 600,
                  }}
                >
                  Active Streak
                </span>
                <strong style={{ fontSize: "16px", color: "var(--text)" }}>
                  {streak} Day{streak !== 1 ? "s" : ""}
