              </div>
            </div>

            {/* Time Studied Tracker */}
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: "12px",
                background: "rgba(255, 255, 255, 0.02)",
                padding: "10px 14px",
                borderRadius: "8px",
                border: "1px solid var(--border)",
              }}
            >
              <div
                style={{
                  fontSize: "20px",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  background: "rgba(52, 211, 153, 0.08)",
                  borderRadius: "50%",
                  width: "40px",
                  height: "40px",
                  border: "1px solid rgba(52, 211, 153, 0.15)",
                  color: "var(--emerald)",
                }}
              >
                ⏱️
              </div>
              <div>
                <span
                  style={{
                    display: "block",
                    fontSize: "11px",
                    color: "var(--muted)",
                    textTransform: "uppercase",
                    fontWeight: 600,
                  }}
                >
                  Time Studied
                </span>
                <strong style={{ fontSize: "16px", color: "var(--text)" }}>
                  {formatStudyTime(progress.minutesStudied || 0)}
                </strong>
              </div>
            </div>

            {/* Daily Goal Target */}
            <div
              onClick={() => setShowGoalModal(true)}
              style={{
                display: "flex",
                alignItems: "center",
                gap: "12px",
                background: "rgba(255, 255, 255, 0.02)",
                padding: "10px 14px",
                borderRadius: "8px",
                border: "1px solid var(--border)",
                cursor: "pointer",
              }}
              title="Click to set daily study goal target"
            >
              <div
                style={{
                  fontSize: "20px",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  background: "rgba(56, 217, 255, 0.08)",
                  borderRadius: "50%",
                  width: "40px",
                  height: "40px",
                  border: "1px solid rgba(56, 217, 255, 0.15)",
                  color: "var(--cyan)",
                }}
              >
                🎯
              </div>
              <div>
                <span
                  style={{
                    display: "block",
                    fontSize: "11px",
                    color: "var(--muted)",
                    textTransform: "uppercase",
                    fontWeight: 600,
                  }}
                >
                  Daily Goal ({dailyGoalMinutes}m)
                </span>
                <strong style={{ fontSize: "16px", color: "var(--cyan)" }}>
                  {goalProgressPct}% Complete
                </strong>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* ADAPTIVE SKILL GRAPH & REPAIR LOOP */}
      <AdaptiveSkillGraph
        completedProblems={progress.solvedProblems}
        completedPuzzles={progress.solvedPuzzles}
        onSelectDrill={() => {
          setActiveView("practice");
        }}
      />

      {/* READINESS WIDGET & 30-DAY JOURNEY ROW */}
      <div
        className="two-col dashboard-major-row"
        style={{ marginBottom: "16px" }}
      >
        {/* READINESS WIDGET */}
        <div
          className="surface-panel readiness-breakdown premium-panel"
          style={{
            padding: isCompact ? "1rem 1.25rem" : "1.25rem 1.5rem",
            borderRadius: "12px",
            border: "1px solid var(--border)",
          }}
        >
          <div
            className="rb-header"
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              marginBottom: "0.75rem",
              borderBottom: "1px solid var(--border)",
              paddingBottom: "0.5rem",
            }}
          >
            <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
              <Target size={16} style={{ color: "var(--cyan)" }} />
              <strong style={{ fontSize: "0.95rem" }}>
                Interview Readiness Breakdown
              </strong>
            </div>
            <button
              onClick={() => toggleWidgetCollapse("readiness")}
              style={{
                background: "transparent",
                border: "none",
                color: "var(--muted)",
                cursor: "pointer",
              }}
            >
              {collapsed["readiness"] ? (
                <ChevronDown size={16} />
              ) : (
                <ChevronUp size={16} />
              )}
            </button>
          </div>

          {!collapsed["readiness"] && (
            <>
              <div
                className="readiness-gauge-container"
                style={{ display: "flex", alignItems: "center", gap: "1.5rem" }}
              >
                {/* Circular Gauge — SVG donut ring */}
                {(() => {
                  const r = 45;
                  const circ = 2 * Math.PI * r;
                  const activeDash = (readiness / 100) * circ;
                  return (
                    <div
                      style={{
                        position: "relative",
                        width: "110px",
                        height: "110px",
                        flexShrink: 0,
                      }}
                    >
                      <svg
                        width="110"
                        height="110"
                        viewBox="0 0 110 110"
                        style={{ display: "block", overflow: "visible" }}
                      >
                        <defs>
                          <linearGradient
                            id="gaugeArcGrad"
                            x1="5"
                            y1="5"
                            x2="105"
                            y2="105"
                            gradientUnits="userSpaceOnUse"
                          >
                            <stop offset="0%" stopColor="#38d9ff" />
                            <stop offset="100%" stopColor="#00a8ff" />
                          </linearGradient>
                        </defs>
                        {/* Background Track */}
                        <circle
                          cx="55"
                          cy="55"
                          r={r}
                          fill="none"
                          stroke="rgba(56,217,255,0.12)"
                          strokeWidth="10"
                        />
                        {/* Active Progress Arc */}
                        <circle
                          cx="55"
                          cy="55"
                          r={r}
                          fill="none"
                          stroke="url(#gaugeArcGrad)"
                          strokeWidth="10"
                          strokeLinecap="round"
                          strokeDasharray={`${activeDash} ${circ}`}
                          strokeDashoffset={0}
                          transform="rotate(-90 55 55)"
                          style={{
                            transition:
                              "stroke-dasharray 0.8s cubic-bezier(0.4, 0, 0.2, 1)",
                          }}
                        />
                      </svg>
                      {/* Centre text */}
                      <div
                        style={{
                          position: "absolute",
                          inset: 0,
                          display: "flex",
                          flexDirection: "column",
                          alignItems: "center",
                          justifyContent: "center",
                          textAlign: "center",
                        }}
                      >
                        <span
                          style={{
                            fontSize: "1.2rem",
                            fontWeight: 800,
                            color: "var(--cyan)",
                            lineHeight: 1.1,
                          }}
                        >
                          {readiness}%
                        </span>
                        <span
                          style={{
                            fontSize: "9px",
                            color: "var(--muted)",
                            fontWeight: 700,
                            letterSpacing: "0.06em",
                            textTransform: "uppercase",
                            marginTop: "2px",
                          }}
                        >
                          READINESS
                        </span>
                      </div>
                    </div>
                  );
                })()}

                {/* Detailed Component Progress Bars */}
                <div
                  className="rb-bars-list"
                  style={{
                    flex: 1,
                    display: "flex",
                    flexDirection: "column",
                    gap: "0.35rem",
                  }}
                >
                  <div className="rb-bar-item">
                    <div
                      className="rb-bar-labels"
                      style={{
                        display: "flex",
                        justifyContent: "space-between",
                        fontSize: "0.75rem",
                        marginBottom: "0.1rem",
                      }}
                    >
                      <span>
                        Modules ({progress.completedModules.length}/
                        {totalModules})
                      </span>
                      <strong>{modPct}%</strong>
                    </div>
                    <div
                      className="rb-bar-track"
                      style={{
                        height: "4px",
                        background: "var(--border)",
                        borderRadius: "2px",
                        overflow: "hidden",
                      }}
                    >
                      <div
                        className="rb-bar-fill fill-emerald"
                        style={{
                          width: `${modPct}%`,
                          height: "100%",
                          background: "var(--emerald)",
                        }}
                      />
                    </div>
                  </div>

                  <div className="rb-bar-item">
                    <div
                      className="rb-bar-labels"
                      style={{
                        display: "flex",
                        justifyContent: "space-between",
                        fontSize: "0.75rem",
                        marginBottom: "0.1rem",
                      }}
                    >
                      <span>
                        Problems ({progress.solvedProblems.length}/
                        {totalProblems})
                      </span>
                      <strong>{probPct}%</strong>
                    </div>
                    <div
                      className="rb-bar-track"
                      style={{
                        height: "4px",
                        background: "var(--border)",
                        borderRadius: "2px",
                        overflow: "hidden",
                      }}
                    >
                      <div
                        className="rb-bar-fill fill-amber"
                        style={{
                          width: `${probPct}%`,
                          height: "100%",
                          background: "var(--amber)",
                        }}
                      />
                    </div>
                  </div>

                  <div className="rb-bar-item">
                    <div
                      className="rb-bar-labels"
                      style={{
                        display: "flex",
                        justifyContent: "space-between",
                        fontSize: "0.75rem",
                        marginBottom: "0.1rem",
                      }}
                    >
                      <span>
                        Puzzles ({(progress.solvedPuzzles || []).length}/
                        {debugPuzzles.length})
                      </span>
                      <strong>{puzPct}%</strong>
                    </div>
                    <div
                      className="rb-bar-track"
                      style={{
                        height: "4px",
                        background: "var(--border)",
                        borderRadius: "2px",
                        overflow: "hidden",
                      }}
                    >
                      <div
                        className="rb-bar-fill fill-cyan"
                        style={{
                          width: `${puzPct}%`,
                          height: "100%",
                          background: "var(--cyan)",
                        }}
                      />
                    </div>
                  </div>

                  <div className="rb-bar-item">
                    <div
                      className="rb-bar-labels"
                      style={{
                        display: "flex",
                        justifyContent: "space-between",
                        fontSize: "0.75rem",
                        marginBottom: "0.1rem",
                      }}
                    >
                      <span>
                        Mock Tests ({mocksTaken}/{coreMocks.length})
                      </span>
                      <strong>{mockPct}%</strong>
                    </div>
                    <div
                      className="rb-bar-track"
                      style={{
                        height: "4px",
                        background: "var(--border)",
                        borderRadius: "2px",
                        overflow: "hidden",
                      }}
                    >
                      <div
                        className="rb-bar-fill fill-violet"
                        style={{
                          width: `${mockPct}%`,
                          height: "100%",
                          background: "var(--violet)",
                        }}
                      />
                    </div>
                  </div>
                </div>
              </div>

              <div
                style={{
                  display: "flex",
                  gap: "0.75rem",
                  marginTop: "0.85rem",
                }}
              >
                <button
                  className="primary-button"
                  onClick={() => setActiveView("mock-runner")}
                  style={{
                    flex: 1,
                    justifyContent: "center",
                    fontSize: "0.8rem",
                    padding: "0.4rem 0.8rem",
                  }}
                >
                  <Trophy size={14} /> Boost Readiness: Take Mock Test
                </button>
              </div>
            </>
          )}
        </div>
      </div>

      {/* COLLAPSIBLE INSIGHTS DRAWER FOR ACHIEVEMENTS & INTERVIEW PREP */}
      <CollapsibleInsightsSection
        totalXP={totalXP}
        currentLevel={currentLevel}
        currentLevelXP={currentLevelXP}
        xpForNextLevel={xpForNextLevel}
        xpProgressPercent={xpProgressPercent}
        earnedBadges={earnedBadges}
        qaItems={qaItems}
        updateEditorQuery={updateEditorQuery}
      />

      {/* DAILY GOAL MODAL */}
      {showGoalModal && (
        <div
          style={{
            position: "fixed",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: "rgba(0,0,0,0.7)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 9999,
          }}
        >
          <div
            className="surface-panel"
            style={{
              width: "360px",
              padding: "20px",
              borderRadius: "10px",
              border: "1px solid var(--cyan)",
              background: "var(--panel)",
            }}
          >
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                marginBottom: "14px",
              }}
            >
              <strong style={{ fontSize: "15px", color: "var(--text)" }}>
                Set Daily Study Goal
              </strong>
              <button
                onClick={() => setShowGoalModal(false)}
                style={{
                  background: "none",
                  border: "none",
                  color: "var(--muted)",
                  cursor: "pointer",
                }}
              >
                <X size={16} />
              </button>
            </div>
            <p
              style={{
                fontSize: "12.5px",
                color: "var(--muted)",
                marginBottom: "16px",
              }}
            >
              Choose your target study duration per day:
            </p>
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "1fr 1fr",
                gap: "10px",
              }}
            >
              {[15, 30, 45, 60].map((mins) => (
                <button
                  key={mins}
                  onClick={() => handleDailyGoalChange(mins)}
                  className={`primary-button ${dailyGoalMinutes === mins ? "" : "outline"}`}
                  style={{
                    justifyContent: "center",
                    padding: "8px",
                    fontSize: "13px",
                  }}
                >
                  {mins} Minutes / Day
                </button>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

