                          fontSize: "9px",
                          background: "rgba(56,217,255,0.08)",
                          color: "var(--cyan)",
                          padding: "1px 6px",
                          borderRadius: "3px",
                          border: "1px solid rgba(56,217,255,0.2)",
                        }}
                      >
                        Core 40
                      </span>
                    )}
                    {roadmapModules.find((m) => m.id === p.moduleId)
                      ?.isHighWeight && (
                      <span
                        style={{
                          fontSize: "9px",
                          background: "rgba(56,217,255,0.08)",
                          color: "var(--cyan)",
                          padding: "1px 6px",
                          borderRadius: "3px",
                          border: "1px solid rgba(56,217,255,0.2)",
                        }}
                      >
                        ⭐ High Weight
                      </span>
                    )}
                  </div>
                  <span
                    style={{
                      fontSize: "14px",
                      fontWeight: 600,
                      textDecoration: solved ? "line-through" : "none",
                      color: solved ? "var(--muted)" : "var(--text)",
                    }}
                  >
                    Solve Practice: {p.title}
                  </span>
                  <span
                    style={{
                      fontSize: "12.5px",
                      color: "var(--text-secondary)",
                      lineHeight: "1.4",
                    }}
                  >
                    {p.prompt.slice(0, 140)}...
                  </span>
                </div>
                <button
                  className="primary-button compact"
                  onClick={() => openInPlayground(p)}
                  style={{ flexShrink: 0, marginTop: "2px" }}
                >
                  Solve
                </button>
              </div>
            );
          })}

          {/* Puzzles Checklist */}
          {dayPuzzles.map((p) => {
            const solved = progress.solvedPuzzles?.includes(p.id);
            return (
              <div
                key={p.id}
                style={{
                  display: "flex",
                  alignItems: "flex-start",
                  gap: "14px",
                  padding: "12px 16px",
                  borderRadius: "6px",
                  border: "1px solid var(--border)",
                  background: solved
                    ? "rgba(48,230,149,0.02)"
                    : "rgba(255,255,255,0.01)",
                  transition: "all 0.2s ease",
                }}
              >
                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    height: "20px",
                  }}
                >
                  <input
                    type="checkbox"
                    checked={solved}
                    readOnly
                    style={{
                      cursor: "not-allowed",
                      width: "16px",
                      height: "16px",
                      accentColor: "var(--emerald)",
                    }}
                  />
                </div>
                <div
                  style={{
                    flexGrow: 1,
                    display: "flex",
                    flexDirection: "column",
                    gap: "4px",
                  }}
                >
                  <div
                    style={{
                      display: "flex",
                      gap: "6px",
                      alignItems: "center",
                      flexWrap: "wrap",
                    }}
                  >
                    <span
                      className={`difficulty-pill ${classForDiff(p.difficulty)}`}
                    >
                      {p.difficulty}
                    </span>
                    <span className="concept-tag">{p.category}</span>
                  </div>
                  <span
                    style={{
                      fontSize: "14px",
                      fontWeight: 600,
                      textDecoration: solved ? "line-through" : "none",
                      color: solved ? "var(--muted)" : "var(--text)",
                    }}
                  >
                    Solve Debug Puzzle: {p.title}
                  </span>
                  <span
                    style={{
                      fontSize: "12.5px",
                      color: "var(--text-secondary)",
                      lineHeight: "1.4",
                    }}
                  >
                    {p.businessScenario}
                  </span>
                </div>
                <button
                  className="primary-button compact"
                  onClick={() => {
                    stopAutoTyping();
                    setActivePuzzleId(p.id);
                    setPlaygroundMode("puzzle");
                    const saved = getSavedPuzzleQuery(p);
                    updateEditorQuery(saved, "puzzle", p.id);
                    setActiveRightTab?.("hints");
                    setActiveView("playground");
                    setQueryResult({ columns: [], rows: [], message: "" });
                    setExpectedResult(null);
                  }}
                  style={{ flexShrink: 0, marginTop: "2px" }}
                >
                  Debug
                </button>
              </div>
            );
          })}

          {/* Mock Test Checklist */}
          {day.mockInterview &&
            (() => {
              const company = day.mockInterview.company;
              const hasScore =
                progress.mockScores &&
                progress.mockScores[company] !== undefined;
              const itemId = `day-${day.day}-mock-${company}`;
              const checked =
                hasScore || progress.completedChecklistItems?.includes(itemId);
              return (
                <div
                  key={itemId}
                  style={{
                    display: "flex",
                    alignItems: "flex-start",
                    gap: "14px",
                    padding: "12px 16px",
                    borderRadius: "6px",
                    border: "1px solid rgba(56,217,255,0.2)",
                    background: checked
                      ? "rgba(48,230,149,0.02)"
                      : "linear-gradient(135deg, rgba(56,217,255,0.02) 0%, rgba(0,0,0,0) 100%)",
                    transition: "all 0.2s ease",
                  }}
                >
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      height: "20px",
                    }}
                  >
                    <input
                      type="checkbox"
                      checked={checked}
                      onChange={() => toggleChecklistItem(itemId)}
                      style={{
                        cursor: "pointer",
                        width: "16px",
                        height: "16px",
                        accentColor: "var(--emerald)",
                      }}
                    />
                  </div>
                  <div
                    style={{
                      flexGrow: 1,
                      display: "flex",
                      flexDirection: "column",
                      gap: "4px",
                    }}
                  >
                    <div
                      style={{
                        display: "flex",
                        gap: "6px",
                        alignItems: "center",
                        flexWrap: "wrap",
                      }}
                    >
                      <span
                        style={{
                          fontSize: "10px",
                          color: "var(--cyan)",
                          textTransform: "uppercase",
                          fontWeight: 600,
                        }}
                      >
                        Milestone Mock Test
                      </span>
                      {hasScore && (
                        <span
                          className="mock-score"
                          style={{ fontSize: "10px", fontWeight: "bold" }}
                        >
                          Score: {progress.mockScores[company]}%
                        </span>
                      )}
                    </div>
                    <span
                      style={{
                        fontSize: "14px",
                        fontWeight: 600,
                        textDecoration: checked ? "line-through" : "none",
                        color: checked ? "var(--muted)" : "var(--text)",
                      }}
                    >
                      Complete Milestone: {company} Mock Interview
                    </span>
                    <span
                      style={{
                        fontSize: "12.5px",
                        color: "var(--text-secondary)",
                        lineHeight: "1.4",
                      }}
                    >
                      This day concludes with a mock interview simulation for{" "}
                      {company}. Make sure to complete the study lessons and
                      practice exercises before attempting the test.
                    </span>
                  </div>
                  <button
                    className="primary-button compact"
                    onClick={() => {
                      setActiveView("mocks");
                    }}
                    style={{ flexShrink: 0, marginTop: "2px" }}
                  >
                    Start Mock Test
                  </button>
                </div>
              );
            })()}
        </div>
      </div>

      {/* Prev / Next Footer Nav */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          marginTop: "2rem",
          borderTop: "1px solid var(--border)",
          paddingTop: "1.5rem",
        }}
      >
        <button
          className="secondary-button compact"
          disabled={day.day === 1}
          onClick={() => setSelectedDayId(day.day - 1)}
          style={{ opacity: day.day === 1 ? 0.3 : 1 }}
        >
          &larr; Day {day.day - 1}
        </button>
        <button
          className="secondary-button compact"
          disabled={day.day === learningRoadmap.length}
          onClick={() => setSelectedDayId(day.day + 1)}
          style={{ opacity: day.day === learningRoadmap.length ? 0.3 : 1 }}
        >
          Day {day.day + 1} &rarr;
        </button>
      </div>
    </div>
  );
}

export default React.memo(DayDetailsView);

import type { PracticeProblem, MockInterview } from "../../data/curriculum";
import type { ViewId, QAItem, MockTestResult } from "../../types";
import React, { Suspense, lazy } from "react";
import {
  Timer,
  CheckCircle2,
  Clock,
  Play,
  AlertTriangle,
  Lightbulb,
  ChevronRight,
  Target,
} from "lucide-react";
import type { BeforeMount, OnMount } from "@monaco-editor/react";
import type { LucideIcon } from "lucide-react";
import type { Difficulty } from "../../data/curriculum";
import { VSplitPane } from "../../components/SplitPane";
import { ErrorBoundary } from "../../components/ErrorBoundary";

import Editor from "@monaco-editor/react";

interface MockTestState {
  company: string;
  questions: PracticeProblem[];
  currentIndex: number;
  answers: { query: string; isCorrect: boolean }[];
  timeRemaining: number;
  isActive: boolean;
}

interface MockTestViewProps {
  activeView: "mocks" | "mock-runner" | "mock-results";
  setActiveView: (view: ViewId) => void;
  progress: {
    mockScores: Record<string, number>;
  };
  mockInterviews: MockInterview[];
  mockHistory: MockTestResult[];
  interviewQuestionBank: QAItem[];
  mockTest: MockTestState | null;
  setMockTest: React.Dispatch<React.SetStateAction<MockTestState | null>>;
  mockReviewIndex: number;
  setMockReviewIndex: (idx: number) => void;
  startMockTest: (
    company: string,
    minutes: number,
    difficulty: string,
    maxModuleId: number,
    questionsCount: number,
  ) => void;
  submitMockAnswer: (sql: string) => void;
  runCurrentQuery: () => void;
  queryRef: React.MutableRefObject<string>;
  queryResult: {
    columns: string[];
    rows: Record<string, unknown>[];
    message: string;
    error?: string;
  };
  resultPage: number;
  setResultPage: React.Dispatch<React.SetStateAction<number>>;
  RESULT_PAGE_SIZE: number;
  updateEditorQuery: (sql: string) => void;

  // Monaco and settings props
  editorTheme: string;
  theme: string;
  query: string;
  handleBeforeMount: BeforeMount;
  handleMount: OnMount;
  handleEditorChange: (val: string | undefined) => void;
  editorMinimap: boolean;
  editorFontSize: number;
  editorFontFamily: string;
  editorTabSize: number;
  editorWordWrap: boolean;
}

function SectionTitle({
  icon: Icon,
  title,
  action,
}: {
  icon: LucideIcon;
  title: string;
  action?: string;
}) {
  return (
    <div className="section-title">
      <div>
        <Icon size={17} />
        <h2>{title}</h2>
      </div>
      {action && <span>{action}</span>}
    </div>
  );
}

function QACard({
  q,
  a,
  followUp,
  mistake,
  onTry,
}: {
  q: string;
  a: string;
  followUp?: string;
  mistake?: string;
  onTry?: (sql: string) => void;
}) {
  const [open, setOpen] = React.useState(false);
  const sqlMatch =
    a.match(/```sql([\s\S]*?)```/) || a.match(/```([\s\S]*?)```/);
  const tryQuery = sqlMatch ? sqlMatch[1].trim() : null;

  return (
    <div className="qa-card">
      <button className="qa-question" onClick={() => setOpen((o) => !o)}>
        <span>{q}</span>
        <ChevronRight size={14} className={open ? "rotated" : ""} />
      </button>
      {open && (
        <div
          className="qa-answer"
          style={{ display: "flex", flexDirection: "column", gap: "8px" }}
        >
          <p style={{ whiteSpace: "pre-wrap" }}>{a}</p>
          {followUp && (
            <p className="qa-followup">
              <strong>Follow-up:</strong> {followUp}
            </p>
          )}
          {mistake && (
            <p className="qa-mistake">
              <strong>Common mistake:</strong> {mistake}
            </p>
          )}
        </div>
      )}
    </div>
  );
}

function MockTestView({
  activeView,
  setActiveView,
  progress,
  mockInterviews,
  mockHistory,
  interviewQuestionBank,
  mockTest,
  setMockTest,
  mockReviewIndex,
  setMockReviewIndex,
  startMockTest,
  submitMockAnswer,
  runCurrentQuery,
  queryRef,
  queryResult,
  resultPage,
  setResultPage,
  RESULT_PAGE_SIZE,
  updateEditorQuery,
  editorTheme,
  theme,
  query,
  handleBeforeMount,
  handleMount,
  handleEditorChange,
  editorMinimap,
  editorFontSize,
  editorFontFamily,
  editorTabSize,
  editorWordWrap,
}: MockTestViewProps) {
  const [editorHeight, setEditorHeight] = React.useState(350);

  function formatTime(seconds: number) {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s < 10 ? "0" : ""}${s}`;
  }

  if (activeView === "mocks") {
    const getWeight = (diff: string): number => {
      const d = (diff || "").toLowerCase();
      if (d === "beginner") return 1;
      if (d.includes("beginner") && d.includes("intermediate")) return 2;
      if (d === "intermediate") return 3;
      if (d.includes("intermediate") && d.includes("advanced")) return 4;
      if (d.includes("advanced") && d.includes("expert")) return 6;
      if (d.includes("advanced")) return 5;
      if (d.includes("expert")) return 7;
      return 99;
    };

    return (
      <div className="view-content">
        <div className="surface-panel">
          <SectionTitle
            icon={Timer}
            title="Mock Interviews"
            action="Company-style SQL rounds"
          />
          <p style={{ color: "var(--muted)", marginBottom: "1.5rem" }}>
            Each mock simulates a real company's DA SQL interview. Study the
            focus areas in the roadmap, then use the playground to attempt the
            round.
          </p>
          <div className="mock-grid">
            {[...mockInterviews]
              .sort((a, b) => {
                const wa = getWeight(a.difficulty);
                const wb = getWeight(b.difficulty);
                if (wa !== wb) return wa - wb;
                return a.company.localeCompare(b.company);
              })
              .map((m) => (
                <article key={m.company} className="mock-card">
                  <div className="mock-head">
                    <h3>{m.company}</h3>
                    <Timer size={17} />
                  </div>
                  <p className="mock-focus">{m.focus}</p>
                  <div className="mock-stats">
                    <span>{m.minutes} min</span>
                    <span>{m.questions} Qs</span>
                    <span
                      className={`difficulty-pill ${
                        m.difficulty.includes("Expert")
                          ? "expert"
                          : m.difficulty.includes("Advanced")
                            ? "hard"
                            : m.difficulty.includes("Intermediate")
                              ? "medium"
                              : "easy"
                      }`}
                    >
                      {m.difficulty}
                    </span>
                  </div>
                  <button
                    className="primary-button compact"
                    onClick={() =>
                      startMockTest(
                        m.company,
                        m.minutes,
                        m.difficulty,
                        m.maxModuleId,
                        m.questions,
                      )
                    }
                  >
                    <Timer size={14} /> Start Test
                  </button>
                  {progress.mockScores[m.company] !== undefined && (
                    <p className="mock-score">
                      Last score: {progress.mockScores[m.company]}% readiness
                    </p>
                  )}
                </article>
              ))}
          </div>
        </div>

        {/* Mock Interview History Log */}
        <div className="surface-panel" style={{ marginTop: "16px" }}>
          <SectionTitle
            icon={Clock}
            title="Mock Interview Attempt History"
            action={`${mockHistory.length} attempts`}
          />
          {mockHistory.length > 0 ? (
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))",
                gap: "12px",
                marginTop: "12px",
              }}
            >
              {mockHistory.map((item) => (
                <div
                  key={item.id}
                  style={{
                    padding: "12px 16px",
                    background: "rgba(255,255,255,0.02)",
                    border: "1px solid var(--border)",
                    borderRadius: "6px",
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                  }}
                >
                  <div>
                    <h4
                      style={{
                        margin: 0,
                        fontSize: "13px",
                        color: "var(--text)",
                      }}
                    >
                      {item.company}
                    </h4>
                    <span style={{ fontSize: "10.5px", color: "var(--muted)" }}>
                      {new Date(item.date).toLocaleDateString()} at{" "}
                      {new Date(item.date).toLocaleTimeString([], {
                        hour: "2-digit",
                        minute: "2-digit",
                      })}
                    </span>
                  </div>
                  <div style={{ textAlign: "right" }}>
                    <span
                      className={`difficulty-pill ${
                        item.score >= 70
                          ? "easy"
                          : item.score >= 40
                            ? "medium"
                            : "hard"
                      }`}
                      style={{ fontWeight: "bold" }}
                    >
                      {item.score}% Score
                    </span>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div
              style={{
                padding: "24px",
                textAlign: "center",
                background: "rgba(255, 255, 255, 0.01)",
                border: "1px dashed var(--border)",
                borderRadius: "6px",
                marginTop: "12px",
                color: "var(--muted)",
                fontSize: "12.5px",
              }}
            >
              No mock interviews completed yet. Choose a company above to begin
              your training!
            </div>
          )}
        </div>

        {/* Interview Q&A Bank */}
        <div className="surface-panel" style={{ marginTop: "16px" }}>
          <SectionTitle
            icon={Target}
            title="Interview Q&A Bank"
            action={`${interviewQuestionBank.length} questions`}
          />
          <div className="qa-list">
            {interviewQuestionBank.map((item) => (
              <QACard
                key={item.question}
                q={item.question}
                a={item.answer}
                followUp={item.followUp}
                mistake={item.mistake}
                onTry={(sql) => {
                  updateEditorQuery(sql);
                  setActiveView("playground");
                }}
              />
            ))}
          </div>
        </div>
      </div>
    );
  }

  if (activeView === "mock-runner") {
    if (!mockTest || !mockTest.isActive) return null;
    const currentQ = mockTest.questions[mockTest.currentIndex];

    return (
      <div className="playground-fullscreen mock-test-mode">
        {/* Editor column */}
        <div className="pg-editor-col">
          <div className="pg-toolbar mock-toolbar">
            <div className="pg-toolbar-left">
              <Timer size={16} />
              <strong>{mockTest.company}</strong>
              <span className="pg-tag">
                Question {mockTest.currentIndex + 1} of{" "}
                {mockTest.questions.length}
              </span>
              <span
                className={`mock-timer ${mockTest.timeRemaining < 300 ? "danger" : ""}`}
              >
                {formatTime(mockTest.timeRemaining)}
              </span>
            </div>
            <div className="pg-toolbar-right">
              <button
                className="primary-button run-btn"
                onClick={runCurrentQuery}
              >
                <Play size={15} /> Run Query
              </button>
              <button
                className="primary-button compact"
                style={{ background: "var(--emerald)", color: "black" }}
                onClick={() => submitMockAnswer(queryRef.current)}
              >
                Submit & Next <CheckCircle2 size={15} />
              </button>
            </div>
          </div>
          {mockTest.timeRemaining <= 300 && (
            <div
              className={`mock-time-warning-banner ${mockTest.timeRemaining <= 60 ? "critical" : "warning"}`}
              style={{
                background:
                  mockTest.timeRemaining <= 60
                    ? "rgba(239, 68, 68, 0.15)"
                    : "rgba(245, 158, 11, 0.15)",
                borderBottom:
                  mockTest.timeRemaining <= 60
                    ? "1px solid #ef4444"
                    : "1px solid #f59e0b",
                color: mockTest.timeRemaining <= 60 ? "#ef4444" : "#f59e0b",
                padding: "8px 16px",
                fontSize: "12px",
                fontWeight: "bold",
                display: "flex",
                alignItems: "center",
                gap: "8px",
              }}
            >
              <AlertTriangle size={14} />
              <span>
                {mockTest.timeRemaining <= 60
                  ? "CRITICAL: Less than 1 minute remaining! Submit your answer immediately!"
                  : `WARNING: Less than 5 minutes remaining (${formatTime(mockTest.timeRemaining)} left)`}
              </span>
            </div>
          )}

          <div
            style={{
              flex: 1,
              overflow: "hidden",
              display: "flex",
              flexDirection: "column",
            }}
          >
            <VSplitPane
              topHeight={editorHeight}
              onResize={setEditorHeight}
              minTop={100}
              maxTop={1000}
              top={
                <div
                  className="pg-editor-wrap"
                  style={{ flex: 1, height: "100%", minHeight: 0 }}
                >
                  <ErrorBoundary fallbackTitle="Mock Query Editor Panel">
                    <Editor
                      height="100%"
                      defaultLanguage="sql"
                      theme={
                        theme === "oled"
                          ? "hc-oled"
                          : theme === "dracula"
                            ? "dracula"
                            : theme === "onedark"
                              ? "one-dark"
                              : theme === "ember"
                                ? "ember"
                                : theme === "light"
                                  ? "vs"
                                  : editorTheme || "vs-dark"
                      }
                      defaultValue={query}
                      beforeMount={handleBeforeMount}
                      onMount={handleMount}
                      onChange={handleEditorChange}
                      options={{
                        minimap: { enabled: editorMinimap },
                        fontSize: editorFontSize,
                        fontFamily: editorFontFamily,
                        tabSize: editorTabSize,
                        insertSpaces: true,
                        padding: { top: 16, bottom: 16 },
                        wordWrap: editorWordWrap ? "on" : "off",
                        bracketPairColorization: { enabled: true },
                        autoClosingBrackets: "always",
                        autoClosingQuotes: "always",
                        tabCompletion: "on",
                        smoothScrolling: true,
                        cursorSmoothCaretAnimation: "on",
                        cursorBlinking: "smooth",
                      }}
                    />
                  </ErrorBoundary>
                </div>
              }
              bottom={
                <div
                  className="pg-result"
                  style={{ flex: 1, height: "100%", minHeight: 0 }}
                >
                  <div className="result-toolbar">
                    <span
                      className={
                        queryResult.error ? "status-dot error" : "status-dot ok"
                      }
                    />
                    <strong>{queryResult.message}</strong>
                  </div>
                  <div className="table-wrap">
                    {queryResult.columns.length > 0 && (
                      <table>
                        <thead>
                          <tr>
                            {queryResult.columns.map((c) => (
                              <th key={c}>{c}</th>
                            ))}
                          </tr>
                        </thead>
                        <tbody>
                          {queryResult.rows
                            .slice(
                              resultPage * RESULT_PAGE_SIZE,
                              (resultPage + 1) * RESULT_PAGE_SIZE,
                            )
                            .map((r, i) => (
                              <tr key={i}>
                                {queryResult.columns.map((c) => (
                                  <td key={c}>{String(r[c] ?? "NULL")}</td>
                                ))}
                              </tr>
                            ))}
                        </tbody>
                      </table>
                    )}
                  </div>
                  {queryResult.rows.length > RESULT_PAGE_SIZE && (
                    <div className="table-pagination">
                      <span>
                        Showing {resultPage * RESULT_PAGE_SIZE + 1}–
                        {Math.min(
                          queryResult.rows.length,
                          (resultPage + 1) * RESULT_PAGE_SIZE,
                        )}{" "}
                        of {queryResult.rows.length} rows
                      </span>
                      <div style={{ display: "flex", gap: "6px" }}>
                        <button
                          disabled={resultPage === 0}
                          onClick={() =>
                            setResultPage((p) => Math.max(0, p - 1))
                          }
                          className="secondary-button compact"
                          style={{ padding: "2px 6px", fontSize: "10px" }}
                        >
                          Prev
                        </button>
                        <button
                          disabled={
                            resultPage >=
                            Math.ceil(
                              queryResult.rows.length / RESULT_PAGE_SIZE,
                            ) -
                              1
                          }
                          onClick={() =>
                            setResultPage((p) =>
                              Math.min(
                                Math.ceil(
                                  queryResult.rows.length / RESULT_PAGE_SIZE,
                                ) - 1,
                                p + 1,
                              ),
                            )
                          }
                          className="secondary-button compact"
                          style={{ padding: "2px 6px", fontSize: "10px" }}
                        >
                          Next
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              }
            />
          </div>
        </div>

        {/* Right side locked to Question prompt */}
        <div className="pg-right-col" style={{ width: 450 }}>
          <div className="pg-tabs">
            <button className="active">
              <Lightbulb size={14} /> Question
            </button>
          </div>
          <div className="pg-tab-content">
            <div className="hint-stack">
              <p className="context-lead">{currentQ.title}</p>
              <div className="hint-scenario">{currentQ.businessScenario}</div>
              <div className="hint-prompt-box">
                <strong>Task</strong>
                <p>{currentQ.prompt}</p>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (activeView === "mock-results") {
    if (!mockTest) return null;
    const score = Math.round(
      (mockTest.answers.filter((a) => a.isCorrect).length /
        mockTest.questions.length) *
        100,
    );
    const q = mockTest.questions[mockReviewIndex];
    const ans = mockTest.answers[mockReviewIndex];
    const isCorrect = ans?.isCorrect ?? false;

    return (
      <div
        className="view-content mock-results-view"
        style={{ display: "flex", flexDirection: "column", height: "100%" }}
      >
        <div
          className="dash-hero"
          style={{ padding: "20px 24px", flexShrink: 0 }}
