            display: "flex",
            flex: 1,
            minHeight: 0,
            gap: "20px",
            padding: "0 24px 24px 24px",
          }}
        >
          {/* Question Sidebar */}
          <div
            className="mock-review-sidebar"
            style={{
              width: "220px",
              background: "var(--panel)",
