              borderRadius: "8px",
              overflowY: "auto",
              display: "flex",
              flexDirection: "column",
              padding: "10px",
            }}
          >
            <h3
              style={{
                fontSize: "11px",
                textTransform: "uppercase",
                color: "var(--muted)",
                padding: "6px 8px",
                borderBottom: "1px solid var(--border)",
                marginBottom: "8px",
              }}
            >
              Questions
            </h3>
            {mockTest.questions.map((item, idx) => {
              const itemCorrect = mockTest.answers[idx]?.isCorrect ?? false;
              const active = mockReviewIndex === idx;
              return (
                <button
                  key={item.id}
                  onClick={() => setMockReviewIndex(idx)}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                    padding: "8px 12px",
                    borderRadius: "6px",
                    marginBottom: "6px",
                    background: active
                      ? "rgba(56, 217, 255, 0.1)"
                      : "transparent",
                    border:
                      "1px solid " +
                      (active ? "rgba(56, 217, 255, 0.3)" : "transparent"),
                    color: active ? "var(--cyan)" : "var(--text)",
                    cursor: "pointer",
                    textAlign: "left",
                    fontSize: "13px",
                    transition: "all 120ms",
                  }}
                >
                  <span>
                    Q{idx + 1}: {item.title.slice(0, 16)}...
                  </span>
                  <span
                    style={{
                      color: itemCorrect ? "var(--emerald)" : "var(--rose)",
                      fontSize: "12px",
                    }}
                  >
                    {itemCorrect ? "✓" : "✗"}
                  </span>
                </button>
              );
            })}
          </div>

          {/* Details Panel */}
          <div
            className="mock-review-detail"
            style={{
              flex: 1,
              background: "var(--panel)",
              border: "1px solid var(--border)",
              borderRadius: "8px",
              padding: "24px",
              overflowY: "auto",
              display: "flex",
              flexDirection: "column",
              gap: "16px",
            }}
          >
            {q ? (
              <>
                <div
                  style={{
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                    borderBottom: "1px solid var(--border)",
                    paddingBottom: "12px",
                  }}
                >
                  <div>
                    <h2 style={{ fontSize: "18px", fontWeight: 700 }}>
                      Q{mockReviewIndex + 1}: {q.title}
                    </h2>
                    <span
                      className={`difficulty-pill ${q.difficulty.toLowerCase()}`}
                      style={{ marginTop: "4px", display: "inline-block" }}
