                      {q.difficulty}
                    </span>
                  </div>
                  <span
                    style={{
                      padding: "6px 12px",
                      borderRadius: "4px",
                      fontSize: "11px",
                      fontWeight: 700,
                      textTransform: "uppercase",
                      background: isCorrect
                        ? "rgba(48, 230, 149, 0.12)"
                        : "rgba(255, 96, 133, 0.12)",
                      color: isCorrect ? "var(--emerald)" : "var(--rose)",
                      border:
                        "1px solid " +
                        (isCorrect
                          ? "rgba(48, 230, 149, 0.2)"
