  setEditorTabSize: (val: number | ((prev: number) => number)) => void;
  editorTheme: string;
  setEditorTheme: (val: string | ((prev: string) => string)) => void;
  theme: "dark" | "light" | "oled" | "dracula" | "onedark" | "ember";
  setTheme: (
    val:
      | "dark"
      | "light"
      | "oled"
      | "dracula"
      | "onedark"
      | "ember"
      | ((
