                        fontSize: "10px",
                      }}
                      aria-label="Close Benchmark Editor"
                    >
                      Close
                    </button>
                  </div>
                  <div style={{ flex: 1, minHeight: 0, position: "relative" }}>
                    <ErrorBoundary fallbackTitle="SQL Editor B Panel">
                      <Editor
                        height="100%"
                        defaultLanguage="sql"
                        loading={
                          <div className="pg-editor-loading" role="status">
                            <span className="pg-editor-loading-dot" />
                            Initializing comparison editor…
                          </div>
                        }
                        theme={
                          editorTheme === "vs-dark" && theme === "oled"
                            ? "hc-oled"
                            : editorTheme
                        }
                        value={queryB}
                        onChange={(val) => handleSetQueryB(val || "")}
                        options={{
                          minimap: { enabled: false },
                          fontSize: editorFontSize - 1,
                          fontFamily: editorFontFamily,
                          tabSize: editorTabSize,
                          insertSpaces: true,
                          lineHeight: 20,
                          padding: { top: 8, bottom: 8 },
                          scrollBeyondLastLine: false,
                          wordWrap: "on",
                          autoClosingBrackets: "always",
                          autoClosingQuotes: "always",
                          tabCompletion: "on",
                          acceptSuggestionOnEnter: "smart",
                          acceptSuggestionOnCommitCharacter: true,
                          lineNumbersMinChars: 4,
                          lineDecorationsWidth: 8,
                          renderLineHighlight: "gutter",
                        }}
                      />
                    </ErrorBoundary>
                  </div>
                  <div
                    style={{
                      padding: "10px",
                      borderTop: "1px solid var(--border)",
                      display: "flex",
                      background: "var(--bg2)",
                      flexShrink: 0,
                    }}
                  >
                    <button
                      onClick={runABBenchmark}
                      className="primary-button compact"
                      style={{
                        flex: 1,
                        background: "var(--violet)",
                        borderColor: "var(--violet)",
                        fontSize: "11px",
                      }}
                    >
                      <Zap size={11} style={{ marginRight: "4px" }} /> Run A/B
                      Benchmark
                    </button>
                  </div>
                </div>
              )}
            </div>
          }
          bottom={
            <div
              className="pg-result"
              style={{
                flex: 1,
                height: "100%",
                minHeight: 0,
                display: "flex",
                flexDirection: "column",
              }}
            >
              <div
                className="result-toolbar"
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  padding: "8px 16px",
                  borderBottom: "1px solid var(--border)",
                }}
              >
                <div
                  style={{ display: "flex", alignItems: "center", gap: "8px" }}
                >
                  <button
                    className={`result-tab ${activeResultTab === "your" ? "active" : ""}`}
                    onClick={() => setActiveResultTab("your")}
                  >
                    <Database size={12} style={{ marginRight: "6px" }} /> Your
                    Result
                  </button>
                  <button
                    className={`result-tab ${activeResultTab === "expected" ? "active" : ""}`}
                    onClick={() => setActiveResultTab("expected")}
                  >
                    <Eye size={12} style={{ marginRight: "6px" }} /> Expected
                    Output
                  </button>
                  {queryResult.durationMs !== undefined &&
                    !queryResult.error && (
                      <span
                        style={{
                          fontSize: "11px",
                          color: "var(--muted)",
                          display: "inline-flex",
                          alignItems: "center",
                          gap: "4px",
                          marginLeft: "6px",
                        }}
                      >
                        <span
                          style={{
                            width: "6px",
                            height: "6px",
                            borderRadius: "50%",
                            background:
                              queryResult.durationMs > 100
                                ? "var(--amber)"
                                : "var(--emerald)",
                            display: "inline-block",
