                        />
                        <span>{queryResult.durationMs.toFixed(2)} ms</span>
                      </span>
                    )}
                </div>

                <div
                  style={{ display: "flex", alignItems: "center", gap: "8px" }}
                >
                  {!queryResult.error &&
                    queryResult.rows &&
                    queryResult.rows.length > 0 && (
                      <button
                        className="secondary-button"
                        style={{ fontSize: "11px", padding: "4px 8px" }}
                        onClick={handleExportCsv}
                        title="Export Results as CSV"
                      >
                        <Download size={12} style={{ marginRight: "4px" }} />{" "}
                        Export CSV
                      </button>
                    )}
                </div>
              </div>

              <div
                style={{
                  display: "flex",
                  flexDirection: "column",
                  flex: 1,
                  minHeight: 0,
                  overflowY: "auto",
                }}
              >
                {graderFeedback && (
                  <div style={{ padding: "12px 12px 0 12px" }}>
                    <div
                      className={`grader-feedback-alert ${graderFeedback.isCorrect ? "success" : "error"}`}
                    >
                      <div className="grader-feedback-title">
                        {graderFeedback.isCorrect
                          ? "✓ Correct!"
                          : "❌ Incorrect"}
                        <span
                          style={{
                            fontSize: "12px",
                            fontWeight: "normal",
                            color: "var(--text-secondary)",
                          }}
                        >
                          - {graderFeedback.message}
                        </span>
                      </div>
                      {graderFeedback.details && (
                        <div
                          style={{
                            fontSize: "11.5px",
                            opacity: 0.85,
                            marginTop: "2px",
                          }}
                        >
                          {graderFeedback.details}
                        </div>
                      )}
                      {graderFeedback.warning && (
                        <div className="grader-feedback-warning">
                          ⚠️ {graderFeedback.warning}
                        </div>
                      )}
                      {!graderFeedback.isCorrect &&
                        selectedProblem &&
                        selectedProblem?.solution &&
                        (() => {
                          const attempts = JSON.parse(
                            localStorage.getItem("sql-aa-failed-attempts") ||
                              "{}",
                          );
                          const failedCount =
                            attempts[selectedProblem?.id] || 0;
                          if (failedCount >= 3) {
                            return (
                              <div
                                style={{
                                  marginTop: "8px",
                                  paddingTop: "8px",
                                  borderTop: "1px solid rgba(255,255,255,0.1)",
                                }}
                              >
                                <button
                                  className="icon-button labeled"
                                  style={{
                                    background: "rgba(56, 217, 255, 0.1)",
                                    color: "var(--cyan)",
                                    border: "1px solid rgba(56, 217, 255, 0.2)",
                                    width: "100%",
                                    justifyContent: "center",
                                    cursor: "pointer",
                                  }}
                                  onClick={() =>
                                    setShowInlineRefSol((prev) => !prev)
                                  }
                                >
                                  <Code2 size={13} />{" "}
                                  {showInlineRefSol
                                    ? "Hide Reference Solution"
                                    : "Compare with Reference Solution (3+ attempts)"}
                                </button>
                                {showInlineRefSol && (
                                  <div
                                    style={{
                                      marginTop: "8px",
                                      background: "#0a0e14",
                                      padding: "10px",
                                      borderRadius: "6px",
                                      border: "1px solid #1f2630",
                                    }}
                                  >
                                    <div
                                      style={{
                                        display: "flex",
                                        justifyContent: "space-between",
                                        alignItems: "center",
                                        marginBottom: "6px",
                                      }}
                                    >
                                      <span
                                        style={{
                                          fontSize: "11px",
                                          fontWeight: 700,
                                          color: "var(--muted)",
                                        }}
                                      >
                                        Reference Solution SQL
                                      </span>
                                      <button
                                        className="icon-button labeled"
                                        style={{
                                          fontSize: "11px",
                                          padding: "2px 8px",
                                        }}
                                        onClick={() =>
                                          updateEditorQuery(
                                            formatSql(
                                              selectedProblem?.solution,
                                            ),
                                          )
                                        }
                                      >
                                        <Play size={11} /> Load into Editor
                                      </button>
                                    </div>
                                    <pre
                                      className="sql-pre small"
                                      style={{ margin: 0 }}
                                    >
                                      {selectedProblem?.solution}
                                    </pre>
                                  </div>
                                )}
                              </div>
                            );
                          }
                          return null;
                        })()}
                    </div>
                  </div>
                )}
