                  className="results-container"
                  style={{
                    display: "flex",
                    gap: "16px",
                    flex: 1,
                    minHeight: 0,
                    overflowY: "auto",
                    padding: "12px",
                  }}
                >
                  {activeResultTab === "expected" ? (
                    <div
                      className="result-half"
                      style={{
                        flex: 1,
                        display: "flex",
                        flexDirection: "column",
                        minWidth: 0,
                        height: "100%",
                        background: "rgba(255,255,255,0.01)",
                        borderRadius: "6px",
                        border: "1px solid var(--border)",
                      }}
                    >
                      <div
                        className="half-header"
                        style={{
                          display: "flex",
                          alignItems: "center",
                          gap: "8px",
                          padding: "8px 12px",
                          borderBottom: "1px solid var(--border)",
                          fontSize: "11px",
                          fontWeight: 600,
                        }}
                      >
                        <span style={{ color: "var(--cyan)" }}>
                          EXPECTED OUTPUT
                        </span>
                      </div>
                      <div style={{ flex: 1, minHeight: 0, overflow: "auto" }}>
                        {expectedResult ? (
                          <ResultTablePanel result={expectedResult} />
                        ) : (
                          <div
                            style={{
                              padding: "20px",
                              color: "var(--muted)",
                              fontSize: "12px",
                            }}
                          >
                            Run query or click to generate expected target
                            output.
                          </div>
                        )}
                      </div>
                    </div>
                  ) : (
                    <div
                      className="result-half"
                      style={{
                        flex: 1,
                        display: "flex",
                        flexDirection: "column",
                        minWidth: 0,
                        height: "100%",
                        background: "rgba(255,255,255,0.01)",
                        borderRadius: "6px",
                        border: "1px solid var(--border)",
                      }}
                    >
                      <div
                        className="half-header"
                        style={{
                          display: "flex",
                          alignItems: "center",
                          gap: "8px",
                          padding: "8px 12px",
                          borderBottom: "1px solid var(--border)",
                          fontSize: "11px",
                          fontWeight: 700,
                          letterSpacing: "0.05em",
                          color: "var(--text-secondary)",
                          background: "rgba(255,255,255,0.02)",
                        }}
                      >
                        <span>YOUR RESULT</span>
                        <span
                          className={
                            queryResult.error
                              ? "status-dot error"
                              : "status-dot ok"
                          }
                        />
