                          style={{
                            fontSize: "10px",
                            fontWeight: 400,
                            color: "var(--muted)",
                            marginRight: "auto",
                          }}
                        >
                          ({queryResult.message})
                        </span>
                        {!queryResult.error &&
                          queryResult.rows &&
                          queryResult.rows.length > 0 && (
                            <div
                              style={{
                                display: "flex",
                                gap: "6px",
                                alignItems: "center",
                              }}
                            >
                              <button
                                onClick={() =>
                                  exportResultAsCsv(
                                    queryResult.columns,
                                    queryResult.rows,
                                  )
                                }
                                title="Export query results as CSV"
                                style={{
                                  background: "rgba(56, 217, 255, 0.08)",
                                  border: "1px solid rgba(56, 217, 255, 0.2)",
                                  borderRadius: "4px",
                                  color: "var(--cyan)",
                                  fontSize: "10px",
                                  fontWeight: 600,
                                  padding: "2px 6px",
                                  cursor: "pointer",
                                  display: "inline-flex",
                                  alignItems: "center",
                                  gap: "3px",
                                }}
                              >
                                <Download size={10} /> CSV
                              </button>
                              <button
                                onClick={() =>
                                  exportResultAsJson(
                                    queryResult.columns,
                                    queryResult.rows,
                                  )
                                }
                                title="Export query results as JSON"
                                style={{
                                  background: "rgba(48, 230, 149, 0.08)",
                                  border: "1px solid rgba(48, 230, 149, 0.2)",
                                  borderRadius: "4px",
                                  color: "var(--emerald)",
                                  fontSize: "10px",
                                  fontWeight: 600,
                                  padding: "2px 6px",
                                  cursor: "pointer",
                                  display: "inline-flex",
                                  alignItems: "center",
                                  gap: "3px",
                                }}
                              >
                                <Download size={10} /> JSON
                              </button>
                            </div>
                          )}
                      </div>
                      <div
                        style={{
                          flex: 1,
                          display: "flex",
                          flexDirection: "column",
                          minHeight: 0,
                          overflow: "hidden",
                          padding: "8px",
                        }}
                      >
                        {queryResult.error ? (
                          renderDetailedError(queryResult.error, query)
                        ) : queryResult.columns.length > 0 ? (
                          <>
                            <div className="table-wrap">
                              <table>
                                <thead>
                                  <tr>
                                    {queryResult.columns.map((c) => (
                                      <th key={c}>{c}</th>
                                    ))}
                                  </tr>
                                </thead>
                                <tbody>
                                  {queryResult.rows
                                    .slice(
                                      resultPage * RESULT_PAGE_SIZE,
                                      (resultPage + 1) * RESULT_PAGE_SIZE,
                                    )
                                    .map((row, i) => (
                                      <tr key={i}>
                                        {queryResult.columns.map((c) => (
                                          <td key={c}>
                                            {String(row[c] ?? "NULL")}
                                          </td>
                                        ))}
                                      </tr>
                                    ))}
                                </tbody>
                              </table>
                            </div>
                            {queryResult.rows.length > RESULT_PAGE_SIZE && (
                              <div className="table-pagination">
                                <span>
                                  Showing {resultPage * RESULT_PAGE_SIZE + 1}–
                                  {Math.min(
                                    queryResult.rows.length,
                                    (resultPage + 1) * RESULT_PAGE_SIZE,
                                  )}{" "}
                                  of {queryResult.rows.length} rows
                                </span>
                                <div style={{ display: "flex", gap: "6px" }}>
                                  <button
                                    disabled={resultPage === 0}
                                    onClick={() =>
                                      setResultPage((p) => Math.max(0, p - 1))
                                    }
                                    className="secondary-button compact"
                                    style={{
                                      padding: "2px 6px",
                                      fontSize: "10px",
                                    }}
                                  >
                                    Prev
                                  </button>
                                  <button
                                    disabled={
                                      resultPage >=
                                      Math.ceil(
                                        queryResult.rows.length /
                                          RESULT_PAGE_SIZE,
                                      ) -
                                        1
                                    }
                                    onClick={() =>
                                      setResultPage((p) =>
                                        Math.min(
                                          Math.ceil(
                                            queryResult.rows.length /
                                              RESULT_PAGE_SIZE,
                                          ) - 1,
                                          p + 1,
                                        ),
                                      )
                                    }
                                    className="secondary-button compact"
                                    style={{
                                      padding: "2px 6px",
                                      fontSize: "10px",
                                    }}
                                  >
                                    Next
                                  </button>
                                </div>
                              </div>
                            )}
                          </>
                        ) : (
                          <div
                            style={{
                              display: "flex",
                              justifyContent: "center",
                              alignItems: "center",
                              height: "100%",
                              color: "var(--muted)",
                              fontSize: "12px",
                            }}
                          >
                            Run your query to see results
                          </div>
                        )}
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </div>
          }
        />
      </div>
    </div>
  );

  const rightContent = (
    <div
      className="pg-right-col"
      style={{ width: "100%", height: "100%", minWidth: 0 }}
    >
      <div className="right-panel-header">
        <strong>Context</strong>
        <div
          className="right-tabs"
          role="tablist"
          aria-label="Context Panel Tabs"
          onKeyDown={handleRightNavKeyDown}
        >
          {tabs.map(({ id, icon: Icon, label }) => (
            <button
              key={id}
              className={activeRightTab === id ? "active" : ""}
              title={label}
              onClick={() => setActiveRightTab(id)}
              role="tab"
              aria-selected={activeRightTab === id}
              tabIndex={activeRightTab === id ? 0 : -1}
              aria-label={label}
              style={{ position: "relative" }}
            >
              <Icon size={15} aria-hidden="true" />
            </button>
          ))}
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: "4px" }}>
          <button
            className="icon-button"
            onClick={toggleContextWidth}
            title={
              playgroundSplit > 520
                ? "Make context panel narrower"
                : "Restore context panel width"
            }
            aria-label={
              playgroundSplit > 520
                ? "Make context panel narrower"
                : "Restore context panel width"
            }
          >
            {playgroundSplit > 520 ? (
              <Minimize2 size={15} />
            ) : (
              <Maximize2 size={15} />
            )}
          </button>
          <button
            className="icon-button"
            onClick={() => setRightOpen(false)}
            title="Close context panel"
            aria-label="Close context panel"
          >
            <X size={15} />
          </button>
        </div>
      </div>

      <div className="right-panel-body">
        {activeRightTab === "schema" && (
          <div className="schema-stack">
            <div
              style={{
                padding: "2px 0 10px 0",
                borderBottom: "1px solid var(--border)",
                marginBottom: "12px",
              }}
            >
              <input
                value={schemaSearch}
                onChange={(e) => setSchemaSearch(e.target.value)}
                placeholder="Search tables or columns..."
                style={{
                  width: "100%",
                  background: "var(--input-bg)",
                  border: "1px solid var(--border)",
                  borderRadius: "4px",
                  padding: "6px 10px",
                  fontSize: "11.5px",
                  outline: "none",
                  color: "var(--text)",
                }}
              />
            </div>

            <div
              onClick={() => setErdModalOpen(true)}
              style={{
                background: "rgba(56, 217, 255, 0.05)",
                border: "1px solid rgba(56, 217, 255, 0.15)",
                borderRadius: "8px",
                padding: "12px 16px",
                marginBottom: "16px",
                cursor: "pointer",
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                gap: "12px",
                transition: "all 0.2s ease",
              }}
              className="erd-launcher-card"
            >
              <div
                style={{ display: "flex", alignItems: "center", gap: "10px" }}
              >
                <Database size={16} style={{ color: "var(--cyan)" }} />
                <div style={{ textAlign: "left" }}>
                  <strong style={{ fontSize: "12.5px", color: "var(--text)" }}>
                    Interactive ERD Explorer
                  </strong>
                  <span
                    style={{
                      display: "block",
                      fontSize: "10px",
                      color: "var(--muted)",
                      marginTop: "1px",
                    }}
                  >
                    Visualize joins & key mappings
                  </span>
                </div>
              </div>
              <ChevronRight size={14} style={{ color: "var(--cyan)" }} />
            </div>
            {(() => {
              const s = schemaSearch.toLowerCase().trim();
              const filteredActive = activeTables.filter(
                (t) =>
                  t.name.toLowerCase().includes(s) ||
                  t.columns.some((c: SchemaColumn) =>
                    c.name.toLowerCase().includes(s),
                  ),
              );
              const filteredOther = otherTables.filter(
                (t) =>
                  t.name.toLowerCase().includes(s) ||
                  t.columns.some((c: SchemaColumn) =>
                    c.name.toLowerCase().includes(s),
                  ),
              );

              return (
                <>
                  {/* Required Tables */}
                  {filteredActive.length > 0 && (
                    <>
                      <div
                        className="schema-section-title"
                        style={{
                          fontSize: "10px",
                          fontWeight: 700,
                          letterSpacing: "0.05em",
                          textTransform: "uppercase",
                          color: "var(--cyan)",
                          marginTop: "16px",
                          marginBottom: "8px",
                          display: "flex",
                          alignItems: "center",
                          gap: "6px",
                        }}
                      >
                        <CheckCircle2 size={11} /> Required Tables
                      </div>
                      {filteredActive.map((t) => (
                        <details
                          key={t.name}
                          id={`schema-table-${t.name}`}
                          open={selectedTable === t.name || undefined}
                          style={{
                            borderLeft:
                              selectedTable === t.name
                                ? "3px solid var(--cyan-bright, #38d9ff)"
                                : "3px solid var(--cyan)",
                            background:
                              selectedTable === t.name
                                ? "rgba(56, 217, 255, 0.04)"
                                : "transparent",
                            paddingLeft: "8px",
                            marginBottom: "12px",
                            borderRadius: "4px",
                            transition: "all 0.2s ease",
                          }}
                        >
                          <summary style={{ listStyle: "none" }}>
                            <div
                              style={{
                                display: "flex",
                                justifyContent: "space-between",
                                alignItems: "center",
                                width: "100%",
                                cursor: "pointer",
                              }}
                            >
                              <span
                                style={{
                                  display: "flex",
                                  alignItems: "center",
                                }}
                              >
                                <strong
                                  className="schema-insertable-item"
                                  style={{
                                    color: "var(--cyan)",
                                    cursor: "pointer",
                                  }}
                                  onClick={(e) => {
                                    e.preventDefault();
                                    e.stopPropagation();
                                    insertTextAtCursor(t.name);
                                  }}
                                  title="Click to insert table name"
                                >
                                  {t.name}
                                </strong>
                                <small
                                  style={{
                                    marginLeft: "8px",
                                    color: "var(--muted)",
                                    fontSize: "10px",
                                  }}
                                >
                                  {t.domain}
                                </small>
                                {t.name.startsWith("temp_") && (
                                  <button
                                    title="Delete custom table"
                                    onClick={(e) => {
                                      e.preventDefault();
                                      e.stopPropagation();
                                      dropCustomTableLocally(t.name);
                                    }}
                                    style={{
                                      background: "none",
                                      border: "none",
                                      color: "var(--rose)",
                                      marginLeft: "8px",
                                      padding: "2px",
                                      cursor: "pointer",
                                      display: "inline-flex",
                                      alignItems: "center",
                                    }}
                                  >
                                    <Trash2 size={11} />
                                  </button>
                                )}
                              </span>
                            </div>
                          </summary>
                          <p
                            style={{
                              fontSize: "12px",
                              color: "var(--text-secondary)",
                              margin: "4px 0 8px 0",
                            }}
                          >
                            {t.description}
