                            {t.columns.map((c: SchemaColumn) => (
                              <div
                                key={c.name}
                                className="schema-insertable-col"
                                style={{
                                  display: "flex",
                                  justifyContent: "space-between",
                                  alignItems: "center",
                                  cursor: "pointer",
                                }}
                              >
                                <div
                                  style={{
                                    display: "flex",
                                    alignItems: "center",
                                    gap: "6px",
                                  }}
                                  onClick={() => insertTextAtCursor(c.name)}
                                  title="Click to insert column name"
                                >
                                  <code>{c.name}</code>
                                  {t.primaryKey === c.name && (
                                    <span
                                      style={{
                                        fontSize: "8px",
                                        padding: "1px 3px",
                                        borderRadius: "3px",
                                        background: "rgba(251, 191, 36, 0.1)",
                                        color: "var(--amber)",
                                        border:
                                          "1px solid rgba(251, 191, 36, 0.25)",
                                        fontWeight: 700,
                                        letterSpacing: "0.02em",
                                      }}
                                    >
                                      PK
                                    </span>
                                  )}
                                  {c.name.endsWith("_id") &&
                                    t.primaryKey !== c.name && (
                                      <span
