                    }

                    const nextPuz =
                      debugPuzzles.findIndex(
                        (x) => x.id === activePuzzle?.id,
                      ) !== -1
                        ? debugPuzzles[
                            debugPuzzles.findIndex(
                              (x) => x.id === activePuzzle?.id,
                            ) + 1
                          ]
                        : null;
                    return nextPuz ? (
                      <button
                        className="primary-button"
                        style={{
                          marginTop: "16px",
                          width: "100%",
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "center",
                          gap: "8px",
                          background: "var(--cyan)",
                          color: "black",
                          fontWeight: "bold",
                        }}
                        onClick={() => openPuzzleInPlayground(nextPuz.id)}
                      >
                        <span>Next Puzzle</span> <ChevronRight size={16} />
                      </button>
                    ) : null;
                  })()}
              </>
            ) : selectedProblem?.id ? (
              <>
                <p
                  className="context-lead"
                  style={{
                    display: "inline-flex",
                    alignItems: "center",
                    gap: "8px",
                    flexWrap: "wrap",
                  }}
                >
                  {selectedProblem?.title}
                  {(() => {
                    const parentMod = roadmapModules.find(
                      (m) => m.id === selectedProblem?.moduleId,
                    );
                    return parentMod?.isHighWeight ? (
                      <span
                        style={{
                          fontSize: "9px",
                          background: "rgba(255,190,61,0.08)",
                          color: "var(--amber)",
                          padding: "1px 6px",
                          borderRadius: "3px",
                          border: "1px solid rgba(255,190,61,0.15)",
                          textTransform: "uppercase",
                          fontWeight: 700,
                          letterSpacing: "normal",
                        }}
                      >
                        ⭐ High Weight
                      </span>
                    ) : null;
                  })()}
                </p>
                <div className="hint-scenario">
                  {selectedProblem?.businessScenario}
                </div>
                <div className="hint-prompt-box">
                  <strong>Task</strong>
                  <p>{selectedProblem?.prompt}</p>
                </div>

                {/* TARGET TABLES & SCHEMA CARD */}
                {relevantTables.length > 0 && (
                  <div
                    style={{
                      background: "rgba(56, 217, 255, 0.04)",
                      border: "1px solid rgba(56, 217, 255, 0.2)",
                      borderRadius: "8px",
                      padding: "10px 12px",
                      margin: "12px 0",
                    }}
                  >
                    <div
                      style={{
                        display: "flex",
                        alignItems: "center",
                        gap: "6px",
                        fontSize: "11px",
                        fontWeight: 700,
                        color: "var(--cyan)",
                        textTransform: "uppercase",
                        letterSpacing: "0.05em",
                        marginBottom: "6px",
                      }}
                    >
                      <Database size={13} /> Target Table
                      {relevantTables.length > 1 ? "s" : ""}:
                    </div>
                    {relevantTables.map((t) => (
                      <div key={t.name} style={{ marginBottom: "6px" }}>
                        <div
                          style={{
                            display: "flex",
                            alignItems: "center",
                            gap: "6px",
                            fontSize: "12px",
                            fontWeight: "bold",
                            color: "var(--text)",
                          }}
                        >
                          Table:{" "}
                          <code
                            style={{
                              background: "rgba(56, 217, 255, 0.15)",
                              color: "var(--cyan)",
                              padding: "1px 6px",
                              borderRadius: "4px",
                            }}
                          >
                            {t.name}
                          </code>
                        </div>
                        <div
                          style={{
                            display: "flex",
                            flexWrap: "wrap",
                            gap: "4px",
                            marginTop: "4px",
                          }}
                        >
                          {t.columns.map((col: SchemaColumn) => (
                            <span
                              key={col.name}
                              style={{
                                fontSize: "10.5px",
                                fontFamily: "var(--font-mono, monospace)",
                                background: "var(--bg)",
                                color: "var(--text-muted)",
                                padding: "2px 6px",
                                borderRadius: "4px",
                                border: "1px solid var(--border)",
                              }}
                            >
                              {col.name}
                            </span>
                          ))}
                        </div>
                      </div>
                    ))}
                  </div>
                )}

                {/* EXPECTED OUTPUT TABLE (HackerRank & DataLemur Style!) */}
                {computedExpectedResult &&
                  !computedExpectedResult.error &&
                  computedExpectedResult.columns.length > 0 && (
                    <div
                      style={{
                        display: "flex",
                        flexDirection: "column",
                        gap: "8px",
                        margin: "14px 0",
                      }}
                    >
                      <strong
                        style={{
                          fontSize: "11px",
                          fontWeight: 700,
                          color: "var(--emerald)",
                          letterSpacing: "0.05em",
                          textTransform: "uppercase",
                          display: "flex",
                          alignItems: "center",
                          gap: "6px",
                        }}
                      >
                        <CheckCircle2 size={13} /> Expected Output Table
                      </strong>
                      <div
                        className="table-wrap"
                        style={{
                          maxHeight: "240px",
                          border: "1px solid var(--border)",
                          borderRadius: "6px",
                          background: "var(--bg2)",
                        }}
                      >
                        <table>
                          <thead>
                            <tr>
                              {computedExpectedResult.columns.map(
                                (c: string) => (
                                  <th key={c}>{c}</th>
                                ),
                              )}
                            </tr>
                          </thead>
                          <tbody>
                            {computedExpectedResult.rows
                              .slice(0, 10)
                              .map(
                                (row: Record<string, unknown>, i: number) => (
                                  <tr key={i}>
                                    {computedExpectedResult.columns.map(
                                      (c: string) => (
                                        <td key={c}>
                                          {String(row[c] ?? "NULL")}
                                        </td>
                                      ),
                                    )}
                                  </tr>
                                ),
                              )}
                          </tbody>
                        </table>
                      </div>
                      {computedExpectedResult.rows.length > 10 && (
                        <span
                          style={{
                            fontSize: "10px",
                            color: "var(--muted)",
                            fontStyle: "italic",
                          }}
                        >
                          Showing first 10 of{" "}
                          {computedExpectedResult.rows.length} total expected
                          rows
                        </span>
                      )}
                    </div>
                  )}
                <div
                  style={{ display: "flex", gap: "8px", marginBottom: "14px" }}
                >
                  <button
                    className="secondary-button compact"
                    style={{
                      flex: 1,
                      display: "inline-flex",
                      alignItems: "center",
                      justifyContent: "center",
                      gap: "6px",
                      padding: "6px 12px",
                      fontSize: "11px",
                      background: "rgba(255,255,255,0.03)",
                      border: "1px solid var(--border)",
                      borderRadius: "4px",
                      cursor: "pointer",
                      color: "var(--text)",
                    }}
                    onClick={() => setLessonModalOpen(true)}
                  >
                    <BookOpen size={13} style={{ color: "var(--cyan)" }} />{" "}
                    Review Lesson
                  </button>
                  <button
                    className="secondary-button compact"
                    style={{
                      flex: 1,
                      display: "inline-flex",
                      alignItems: "center",
                      justifyContent: "center",
                      gap: "6px",
                      padding: "6px 12px",
                      fontSize: "11px",
                      background: "rgba(255,255,255,0.03)",
                      border: "1px solid var(--border)",
                      borderRadius: "4px",
                      cursor: "pointer",
                      color: "var(--text)",
                    }}
                    onClick={resetPlayground}
                  >
                    <RefreshCcw size={13} style={{ color: "var(--cyan)" }} />{" "}
                    Reset Starter SQL
                  </button>
                </div>
                {(() => {
                  const targetSolution =
                    playgroundMode === "puzzle" && activePuzzle
                      ? activePuzzle?.solutionQuery
                      : selectedProblem?.solution || "";

                  const problemTitle =
                    playgroundMode === "puzzle" && activePuzzle
                      ? activePuzzle?.title
                      : selectedProblem?.title || "Problem";

                  const rawHints =
                    playgroundMode === "puzzle" && activePuzzle
                      ? activePuzzle?.hints && activePuzzle?.hints.length >= 3
                        ? activePuzzle?.hints
                        : [
                            activePuzzle?.hint ||
                              `Analyze the flawed query: inspect table joins, aliases, and WHERE filters.`,
                            `Identify syntax mismatches, join condition errors, or incorrect aggregate grouping.`,
                            `Compare your modified query against expected columns and target output rows.`,
                          ]
                      : selectedProblem?.hints &&
                          selectedProblem?.hints.length >= 3
                        ? selectedProblem?.hints
                        : [
                            `Inspect the '${problemTitle}' objective and schema in the Instructions tab.`,
                            `Draft your query: SELECT columns, FROM table, apply filters, and ORDER BY as requested.`,
                            `Format your final output columns and apply sorting as specified in the scenario.`,
                          ];

                  const displayHints = rawHints;

                  return (
                    <>
                      {displayHints
                        .slice(0, visibleHints)
                        .map((h: string, i: number) => (
                          <div key={i} className="hint-card">
                            <Lightbulb size={13} />
                            <span>
                              <strong>Hint {i + 1} of 3:</strong> {h}
                            </span>
                          </div>
                        ))}
                      {visibleHints < displayHints.length && (
                        <button
                          className="get-next-hint-btn"
                          onClick={() =>
                            setVisibleHints((n) =>
                              Math.min(displayHints.length, n + 1),
                            )
                          }
                          style={{
                            display: "flex",
                            alignItems: "center",
                            justifyContent: "center",
                            gap: "8px",
                            width: "100%",
                            padding: "9px 14px",
                            margin: "10px 0 14px 0",
                            background: "rgba(56, 217, 255, 0.08)",
                            border: "1px solid rgba(56, 217, 255, 0.25)",
                            borderRadius: "6px",
                            color: "var(--cyan)",
                            fontWeight: 600,
                            fontSize: "12.5px",
                            cursor: "pointer",
                            transition: "all 0.2s ease",
                          }}
                        >
                          <Lightbulb size={14} />{" "}
                          {visibleHints === 0
                            ? "Unlock Hint"
                            : "Unlock Next Hint"}{" "}
                          ({displayHints.length - visibleHints} remaining)
                        </button>
                      )}
                    </>
                  );
                })()}
                <button
                  className="reveal-answer-btn"
                  onClick={() => {
                    if (!solutionRevealed) {
                      showConfirm(
                        "Are you sure you want to reveal the answer? Try using the hints first!",
                        () => {
                          setSolutionRevealed(true);
                        },
                      );
                    } else {
                      setSolutionRevealed(false);
                    }
                  }}
                >
                  <Sparkles size={14} />
                  {solutionRevealed ? "Hide Answer" : "Reveal Answer"}
                </button>
                {solutionRevealed && (
                  <div className="hint-solution">
                    <pre className="sql-pre small">
                      {formatSql(selectedProblem?.solution)}
                    </pre>
                    <div className="sol-actions">
                      <button
                        className="icon-button labeled"
                        onClick={() => {
                          updateEditorQuery(
                            formatSql(selectedProblem?.solution),
                          );
                        }}
                      >
                        <Play size={13} /> Load into Editor
                      </button>
                    </div>
                    <p className="sol-explanation">
                      {selectedProblem?.detailedExplanation}
                    </p>
                  </div>
                )}

                {(() => {
                  const dialect = getDialectNotes(selectedProblem?.moduleId);
                  if (!dialect) return null;
                  return (
                    <details
                      style={{
                        marginTop: "16px",
                        background: "var(--panel)",
                        border: "1px solid var(--border)",
                        borderRadius: "6px",
                        padding: "8px 12px",
                      }}
                    >
                      <summary
                        style={{
                          cursor: "pointer",
                          fontWeight: "bold",
                          fontSize: "11px",
                          display: "flex",
                          alignItems: "center",
                          gap: "6px",
                          color: "var(--cyan)",
                          textTransform: "uppercase",
                        }}
                      >
                        <Database size={13} /> Dialect Notes ({dialect.title})
                      </summary>
                      <pre
                        style={{
                          marginTop: "8px",
                          whiteSpace: "pre-wrap",
                          fontSize: "11px",
                          lineHeight: "1.4",
                          color: "var(--text-secondary)",
                          fontFamily: "var(--font-mono)",
                          margin: 0,
                        }}
                      >
                        {dialect.notes}
                      </pre>
                    </details>
                  );
                })()}

                {progress.solvedProblems.includes(selectedProblem?.id) && (
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: "6px",
                      padding: "8px 12px",
                      margin: "10px 0",
                      background: "rgba(48, 230, 149, 0.08)",
                      border: "1px solid rgba(48, 230, 149, 0.25)",
                      borderRadius: "6px",
                      color: "var(--emerald)",
                      fontSize: "12px",
                      fontWeight: 700,
                    }}
                  >
                    <CheckCircle2 size={15} /> Solved ✓
                  </div>
                )}
                {(() => {
                  const idx = allProblems.findIndex(
                    (p) => p.id === selectedProblem?.id,
                  );
                  const nextProb =
                    idx !== -1 && idx < allProblems.length - 1
                      ? allProblems[idx + 1]
                      : null;
                  return nextProb ? (
                    <button
                      className="primary-button"
                      style={{
                        marginTop: "12px",
                        width: "100%",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        gap: "8px",
                        background: "var(--cyan)",
                        color: "black",
                        fontWeight: "bold",
                      }}
                      onClick={() => openInPlayground(nextProb)}
                    >
                      <span>Next Problem &rarr;</span>
                    </button>
                  ) : null;
                })()}
              </>
            ) : (
              <div className="no-problem">
                <Lightbulb size={28} />
                <p>
                  Open a problem from <strong>Practice</strong> to see hints and
                  the question here.
                </p>
                <button
                  className="primary-button compact"
                  onClick={() => setActiveView("practice")}
                >
                  <Code2 size={14} /> Browse Problems
                </button>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );

  return (
    <div className="playground-fullscreen">
      {showSplit ? (
        <SplitPane
          leftWidth={playgroundSplit}
          onResize={handlePlaygroundSplitResize}
          minLeft={400}
          maxLeft={1600}
          left={rightContent}
          right={editorContent}
        />
      ) : (
        editorContent
      )}

      {!rightOpen && !editorMaximized && (
        <button
          className="pg-left-toggle"
          title="Show Context Panel"
          onClick={() => setRightOpen(true)}
        >
          <Database size={16} />
        </button>
      )}

      {erdModalOpen && (
        <ErdModalView
          setErdModalOpen={setErdModalOpen}
          tableSchemas={tableSchemas}
          liveSchema={liveSchema}
        />
      )}

      {lessonModalOpen && activeModule && (
        <div
          className="custom-modal-overlay"
          onClick={() => setLessonModalOpen(false)}
        >
          <div
            className="custom-modal-window large"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="custom-modal-header">
              <h2>
                <BookOpen size={18} />
                <span>
                  Lesson: {activeModule.title} (Module {activeModule.id})
                </span>
              </h2>
              <button
                className="icon-button"
                onClick={() => setLessonModalOpen(false)}
              >
                <X size={16} />
              </button>
            </div>
            <div className="custom-modal-body">
              <div className="concept-tab-container">
                <LessonProse text={activeModule.lesson.conceptExplanation} />

                {activeModule.lesson.realBusinessScenario && (
                  <div
                    className="concept-scenario-section"
                    style={{ marginTop: "24px" }}
                  >
                    <h3
                      className="section-title-visual"
                      style={{
                        fontSize: "13px",
                        display: "flex",
                        alignItems: "center",
                        gap: "6px",
                        fontWeight: 700,
                        color: "var(--text)",
                        marginBottom: "8px",
                      }}
                    >
                      <Lightbulb
                        size={15}
                        style={{ color: "var(--yellow)", marginRight: "6px" }}
                      />
                      Real-World Business Scenario
                    </h3>
                    <LessonProse
                      text={activeModule.lesson.realBusinessScenario}
                    />
                  </div>
                )}

                {activeModule.lesson.visualExplanation && (
                  <div
                    className="concept-visual-section"
                    style={{ marginTop: "24px" }}
                  >
                    <h3
                      className="section-title-visual"
                      style={{
                        fontSize: "13px",
                        display: "flex",
                        alignItems: "center",
                        gap: "6px",
                        fontWeight: 700,
                        color: "var(--text)",
                        marginBottom: "8px",
                      }}
                    >
                      <Eye
                        size={15}
                        style={{ color: "var(--cyan)", marginRight: "6px" }}
                      />
                      Visual Representation
                    </h3>
                    <LessonProse text={activeModule.lesson.visualExplanation} />
                  </div>
                )}
              </div>
            </div>
            <div className="custom-modal-footer">
              <button
                className="primary-button"
                onClick={() => setLessonModalOpen(false)}
              >
                Back to Practice
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
});

export default PlaygroundView;

import { setStorageItem } from "../../utils/storage";
import React, { useState, useMemo } from "react";
import {
  Code2,
  Zap,
  CheckCircle2,
  Lightbulb,
  Sparkles,
  Play,
  ChevronRight,
} from "lucide-react";
import type { LucideIcon } from "lucide-react";
import type {
  RoadmapModule,
  PracticeProblem,
  Difficulty,
} from "../../data/curriculum";
import { SplitPane } from "../../components/SplitPane";
import { useLocalStorage } from "../../hooks/useLocalStorage";
import type { ViewId, PlaygroundMode } from "../../types";

interface PracticeViewProps {
  progress: {
    completedModules: number[];
    solvedProblems: string[];
  };
  activeModuleId: number;
  roadmapModules: RoadmapModule[];
  selectedProblem: PracticeProblem;
  selectProblem: (p: PracticeProblem) => void;
  openInPlayground: (p: PracticeProblem) => void;
  markProblemSolved: (p: PracticeProblem, quality?: number) => void;
  updateEditorQuery: (
    newVal: string,
    pMode?: PlaygroundMode,
    targetId?: string,
    moveCursorToEnd?: boolean,
  ) => void;
  copyToClipboard: (text: string) => void;
  classForDiff: (d: Difficulty) => string;
  selectModule: (m: RoadmapModule) => void;
  setActiveView: (view: ViewId) => void;
  setPlaygroundMode: (mode: "practice" | "puzzle" | "free") => void;
}

function SectionTitle({
  icon: Icon,
  title,
  action,
}: {
  icon: LucideIcon;
  title: string;
  action?: string;
}) {
  return (
    <div className="section-title">
      <div>
        <Icon size={17} />
        <h2>{title}</h2>
      </div>
      {action && <span>{action}</span>}
    </div>
  );
}

function PracticeView({
  progress,
  activeModuleId,
  roadmapModules,
  selectedProblem,
  selectProblem,
  openInPlayground,
  markProblemSolved,
  updateEditorQuery,
  copyToClipboard,
  classForDiff,
  selectModule,
  setActiveView,
  setPlaygroundMode,
}: PracticeViewProps) {
  // Scoped states pushed down from App
  const [practiceSplit, setPracticeSplit] = useState(() => {
    try {
      const saved = localStorage.getItem("sql-aa-split-practice");
      return saved ? JSON.parse(saved) : 340;
    } catch {
      return 340;
    }
  });
  const handlePracticeSplitResize = (w: number) => {
    setPracticeSplit(w);
    setStorageItem("sql-aa-split-practice", JSON.stringify(w));
  };

  const [diffFilter, setDiffFilter] = useState<Difficulty | "All">("All");
  const [companyFilter, setCompanyFilter] = useState<string>("All");
  const [selectedConceptFilter, setSelectedConceptFilter] =
    useState<string>("All");
  const [showOnlyEssential, setShowOnlyEssential] = useState(false);
  const [visibleHints, setVisibleHints] = useState(0);
  const [solutionRevealed, setSolutionRevealed] = useState(false);

  // Derive static list of companies and concepts
  const activeModule = useMemo(
    () =>
      roadmapModules.find((m) => m.id === activeModuleId) ?? roadmapModules[0],
    [activeModuleId, roadmapModules],
  );

  const allProblems = useMemo(
    () => roadmapModules.flatMap((m) => m.problems),
    [roadmapModules],
  );

  const availableCompanies = useMemo(() => {
    const companies = new Set<string>();
    allProblems.forEach((p) => {
      if (p.companyTags) {
        p.companyTags.forEach((tag) => {
          if (tag) companies.add(tag);
        });
      }
    });
    return Array.from(companies).sort();
  }, [allProblems]);

  const availableConcepts = useMemo(() => {
    return activeModule.problems.reduce((acc, p) => {
      if (p.concepts) {
        p.concepts.forEach((c) => {
          if (!acc.includes(c)) acc.push(c);
        });
      }
      return acc;
    }, [] as string[]);
  }, [activeModule.problems]);

  const visibleProblems = useMemo(() => {
    return activeModule.problems.filter(
      (p) =>
        (diffFilter === "All" || p.difficulty === diffFilter) &&
        (companyFilter === "All" ||
          (p.companyTags && p.companyTags.includes(companyFilter))) &&
        (selectedConceptFilter === "All" ||
          (p.concepts && p.concepts.includes(selectedConceptFilter))) &&
        (!showOnlyEssential ||
          p.isEssential ||
          p.difficulty === "Easy" ||
          p.difficulty === "Medium"),
    );
  }, [
    activeModule.problems,
    diffFilter,
    companyFilter,
    selectedConceptFilter,
    showOnlyEssential,
  ]);

  // Reset visual hints & answer when active problem changes
  React.useEffect(() => {
    setVisibleHints(0);
    setSolutionRevealed(false);
  }, [selectedProblem.id]);

  return (
    <SplitPane
      leftWidth={practiceSplit}
      onResize={handlePracticeSplitResize}
      minLeft={220}
      maxLeft={520}
      left={
        <div className="practice-list-panel surface-panel full-height">
          <SectionTitle
            icon={Code2}
            title="Practice Problems"
            action={activeModule.title}
          />
          <div className="segmented">
            {(["All", "Easy", "Medium", "Hard"] as const).map((d) => (
              <button
                key={d}
                className={diffFilter === d ? "active" : ""}
                onClick={() => setDiffFilter(d)}
              >
                {d}
              </button>
            ))}
          </div>
          <div
            className="module-selector"
            style={{ display: "flex", gap: "8px", marginBottom: "12px" }}
          >
            <select
              value={companyFilter}
              onChange={(e) => setCompanyFilter(e.target.value)}
              style={{ flex: 1 }}
            >
              <option value="All">All Companies</option>
              {availableCompanies.map((c) => (
                <option key={c} value={c}>
                  {c}
                </option>
              ))}
            </select>
            <select
              value={selectedConceptFilter}
              onChange={(e) => setSelectedConceptFilter(e.target.value)}
              style={{ flex: 1 }}
            >
              <option value="All">All Concepts</option>
              {availableConcepts.map((c) => (
                <option key={c} value={c}>
                  {c}
                </option>
              ))}
            </select>
          </div>
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: "8px",
              padding: "0 24px",
              marginBottom: "16px",
            }}
          >
            <input
              type="checkbox"
              id="essential-toggle"
              checked={showOnlyEssential}
              onChange={(e) => setShowOnlyEssential(e.target.checked)}
            />
            <label
              htmlFor="essential-toggle"
              style={{ fontSize: "13px", color: "var(--fg-dim)" }}
            >
              Show only Essential Problems (Core 40)
            </label>
          </div>
          <div className="module-selector">
            <select
              value={activeModuleId}
              onChange={(e) => {
                const m = roadmapModules.find(
                  (x) => x.id === Number(e.target.value),
                );
                if (m) selectModule(m);
              }}
            >
              {roadmapModules.map((m) => (
                <option key={m.id} value={m.id}>
                  {m.isHighWeight ? "⭐ " : ""}M{m.id}: {m.title}
