          </div>
          <div className="problem-list">
            {visibleProblems.map((p) => (
              <article
                key={p.id}
                className={`problem-card ${selectedProblem.id === p.id ? "selected" : ""}`}
              >
                <button
                  className="problem-main"
                  onClick={() => selectProblem(p)}
