                  <button
                    className="icon-button"
                    title="Open in Playground"
                    onClick={() => openInPlayground(p)}
                  >
                    <Zap size={14} />
                  </button>
                  <span
                    className={`status-icon ${progress.solvedProblems.includes(p.id) ? "solved" : ""}`}
                    title={
                      progress.solvedProblems.includes(p.id)
                        ? "Solved"
                        : "Unsolved"
                    }
                    style={{
                      display: "inline-flex",
                      alignItems: "center",
                      justifyContent: "center",
                      color: progress.solvedProblems.includes(p.id)
                        ? "var(--emerald)"
                        : "var(--muted)",
                    }}
                  >
                    <CheckCircle2 size={14} />
                  </span>
                </div>
              </article>
            ))}
          </div>
        </div>
      }
      right={
        <div className="problem-detail-panel surface-panel full-height">
          <div className="problem-detail-header">
            <div
              style={{
                display: "flex",
                gap: "6px",
                alignItems: "center",
                flexWrap: "wrap",
              }}
            >
              <span
                className={`difficulty-pill ${classForDiff(selectedProblem.difficulty)}`}
              >
                {selectedProblem.difficulty}
              </span>
              {selectedProblem.companyTags?.map((tag) => (
                <span key={tag} className="company-tag">
                  {tag}
                </span>
              ))}
              {(() => {
                const parentMod = roadmapModules.find(
                  (m) => m.id === selectedProblem.moduleId,
                );
                return parentMod?.isHighWeight ? (
                  <span
                    style={{
                      fontSize: "9px",
                      background: "rgba(255,190,61,0.08)",
                      color: "var(--amber)",
                      padding: "1px 6px",
                      borderRadius: "3px",
                      border: "1px solid rgba(255,190,61,0.15)",
                      textTransform: "uppercase",
                      fontWeight: 700,
                    }}
                  >
                    ⭐ High Interview Weight
                  </span>
                ) : null;
              })()}
            </div>
            <h2>{selectedProblem.title}</h2>
          </div>
          <div className="problem-scenario">
            <strong>Scenario:</strong> {selectedProblem.businessScenario}
          </div>
          <div className="problem-prompt-box">
            <strong>Task:</strong>
            <p>{selectedProblem.prompt}</p>
          </div>
          <div className="problem-concepts">
            {selectedProblem.concepts.map((c) => (
              <span key={c} className="concept-tag">
                {c}
              </span>
            ))}
          </div>
          <div className="hint-actions">
            <button
              className="primary-button compact"
              onClick={() => openInPlayground(selectedProblem)}
            >
              <Zap size={15} /> Open in Playground
            </button>
            <button
              className="icon-button labeled"
              onClick={() =>
                setVisibleHints((n) =>
                  Math.min(selectedProblem.hints.length, n + 1),
                )
              }
            >
              <Lightbulb size={14} /> Hint
            </button>
            <button
              className="icon-button labeled"
              onClick={() => setSolutionRevealed(true)}
            >
              <Sparkles size={14} /> Reveal Answer
            </button>
            {progress.solvedProblems.includes(selectedProblem.id) && (
              <span
                style={{
                  fontSize: "12px",
                  color: "var(--emerald)",
                  fontWeight: "bold",
                  display: "inline-flex",
                  alignItems: "center",
                  gap: "4px",
                }}
              >
                <CheckCircle2 size={14} /> Solved ✓
              </span>
            )}
          </div>
          <div className="hint-stack">
            {selectedProblem.hints.slice(0, visibleHints).map((h, i) => (
              <div key={i} className="hint-card">
                <Lightbulb size={13} />
                {h}
              </div>
            ))}
            {solutionRevealed && (
              <div className="solution-card">
                <h3>Solution</h3>
                <pre className="sql-pre">{selectedProblem.solution}</pre>
                <p>{selectedProblem.detailedExplanation}</p>
                <p>
                  <strong>Alternative:</strong>{" "}
                  {selectedProblem.alternativeApproach}
                </p>
                <p>
                  <strong>Performance:</strong>{" "}
                  {selectedProblem.performanceNotes}
                </p>
                <button
                  className="icon-button labeled"
                  onClick={() => {
                    setPlaygroundMode("practice");
                    updateEditorQuery(selectedProblem.solution);
                    setActiveView("playground");
                  }}
                >
                  <Play size={14} /> Run in Playground
                </button>
              </div>
            )}
          </div>
          {progress.solvedProblems.includes(selectedProblem.id) &&
            (() => {
              const idx = allProblems.findIndex(
                (p) => p.id === selectedProblem.id,
              );
              const nextProb =
                idx !== -1 && idx < allProblems.length - 1
                  ? allProblems[idx + 1]
                  : null;
              return nextProb ? (
                <button
                  className="primary-button"
                  style={{
                    marginTop: "16px",
                    width: "100%",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    gap: "8px",
                    background: "var(--cyan)",
                    color: "black",
                    fontWeight: "bold",
                  }}
                  onClick={() => selectProblem(nextProb)}
                >
                  <span>Next Problem</span> <ChevronRight size={16} />
                </button>
              ) : null;
            })()}
        </div>
      }
    />
  );
}

export default React.memo(PracticeView);

import { setStorageItem } from "../../utils/storage";
import React, { useState, useMemo, useEffect } from "react";
import { Bug, CheckCircle2, Lightbulb, Sparkles, Play } from "lucide-react";
import type { Difficulty } from "../../data/curriculum";
import { SplitPane } from "../../components/SplitPane";

interface PuzzlesViewProps {
  progress: {
    completedModules: number[];
    solvedProblems: string[];
    solvedPuzzles: string[];
  };
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  debugPuzzles: any[];
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  activePuzzle: any;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  setActivePuzzleId: (id: string) => void;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  openPuzzleInPlayground: (p: any) => void;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  markPuzzleSolved: (p: any) => void;
  updateEditorQuery: (
    newVal: string,
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    pMode?: any,
    targetId?: string,
    moveCursorToEnd?: boolean,
  ) => void;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  setActiveView: (view: any) => void;
  setPlaygroundMode: (mode: "practice" | "puzzle" | "free") => void;
  classForDiff: (d: Difficulty) => string;
}

function PuzzlesView({
  progress,
  debugPuzzles,
  activePuzzle,
  setActivePuzzleId,
  openPuzzleInPlayground,
  markPuzzleSolved,
  updateEditorQuery,
  setActiveView,
  setPlaygroundMode,
  classForDiff,
}: PuzzlesViewProps) {
  // Scoped states pushed down from App
  const [puzzleSplit, setPuzzleSplit] = useState(() => {
    try {
      const saved = localStorage.getItem("sql-aa-split-puzzle");
      return saved ? JSON.parse(saved) : 340;
    } catch {
      return 340;
    }
  });
  const handlePuzzleSplitResize = (w: number) => {
    setPuzzleSplit(w);
    setStorageItem("sql-aa-split-puzzle", JSON.stringify(w));
  };

  const [puzzleCategoryFilter, setPuzzleCategoryFilter] = useState("All");
  const [solutionRevealed, setSolutionRevealed] = useState(false);

  const visiblePuzzles = useMemo(() => {
    return debugPuzzles.filter(
      (p) =>
        puzzleCategoryFilter === "All" || p.category === puzzleCategoryFilter,
    );
  }, [debugPuzzles, puzzleCategoryFilter]);

  // Reset answer revealed state when active puzzle changes
  useEffect(() => {
    setSolutionRevealed(false);
  }, [activePuzzle.id]);

  return (
    <SplitPane
      leftWidth={puzzleSplit}
      onResize={handlePuzzleSplitResize}
      left={
        <div className="practice-list-panel surface-panel full-height">
          <div className="band-label">
            <h3>Debug Puzzles</h3>
            <span>
              {visiblePuzzles.length} Filtered / {debugPuzzles.length} Total
            </span>
          </div>
          <div
            style={{
              padding: "0 24px 12px 24px",
              borderBottom: "1px solid var(--border)",
              marginBottom: "16px",
            }}
          >
            <select
              value={puzzleCategoryFilter}
              onChange={(e) => {
                setPuzzleCategoryFilter(e.target.value);
                const firstFiltered = debugPuzzles.find(
                  (x) =>
                    e.target.value === "All" || x.category === e.target.value,
                );
                if (firstFiltered) setActivePuzzleId(firstFiltered.id);
              }}
              style={{
                width: "100%",
                background: "var(--input-bg)",
                border: "1px solid var(--border)",
                color: "var(--text)",
                padding: "6px",
                borderRadius: "4px",
                fontSize: "12px",
                outline: "none",
              }}
            >
              <option value="All">All Categories</option>
              <option value="Aggregation">Aggregation & Group By</option>
              <option value="JOINs & Subqueries">JOINs & Subqueries</option>
              <option value="Window Functions">
                Window Functions & Analytics
              </option>
              <option value="Syntax & Logic">Syntax & Logic Hazards</option>
            </select>
          </div>
          <div className="problem-list">
            {visiblePuzzles.map((p) => {
              const isSolved = progress.solvedPuzzles?.includes(p.id);
              return (
                <article
                  key={p.id}
                  className={`problem-card ${
                    activePuzzle.id === p.id ? "selected" : ""
                  } ${isSolved ? "solved" : ""}`}
                  onClick={() => setActivePuzzleId(p.id)}
                >
                  <div className="problem-main">
                    <div
                      style={{
                        display: "flex",
                        alignItems: "center",
                        gap: "6px",
                        marginBottom: "4px",
                      }}
                    >
                      <span
                        className={`difficulty-pill ${classForDiff(p.difficulty)}`}
                      >
                        {p.difficulty}
                      </span>
                      {isSolved && (
                        <span
                          style={{
                            color: "var(--emerald)",
                            display: "inline-flex",
                            alignItems: "center",
                            fontSize: "11px",
                            fontWeight: 600,
                          }}
                        >
                          <CheckCircle2
                            size={11}
                            style={{ marginRight: "2px" }}
                          />{" "}
                          Solved
                        </span>
                      )}
                    </div>
                    <h3>{p.title}</h3>
                    <p>{p.category}</p>
                  </div>
                  <div className="problem-actions">
                    <button
                      className="icon-button animate-trigger"
                      title="Debug in Playground"
                      onClick={(e) => {
                        e.stopPropagation();
                        openPuzzleInPlayground(p);
                      }}
                    >
                      <Bug size={14} />
                    </button>
                    <span
                      className={`status-icon ${isSolved ? "solved" : ""}`}
                      title={isSolved ? "Solved" : "Unsolved"}
                      style={{
                        display: "inline-flex",
                        alignItems: "center",
                        justifyContent: "center",
                        color: isSolved ? "var(--emerald)" : "var(--muted)",
                      }}
                    >
                      <CheckCircle2 size={14} />
                    </span>
                  </div>
                </article>
              );
            })}
          </div>
        </div>
      }
      right={
        <div className="problem-detail-panel surface-panel full-height">
          <div className="problem-detail-header">
            <div style={{ display: "flex", gap: "6px", alignItems: "center" }}>
              <span
                className={`difficulty-pill ${classForDiff(activePuzzle.difficulty)}`}
              >
                {activePuzzle.difficulty}
              </span>
              <span className="concept-tag">{activePuzzle.category}</span>
              {progress.solvedPuzzles?.includes(activePuzzle.id) && (
                <span
                  className="solved-badge"
                  style={{
                    display: "inline-flex",
                    alignItems: "center",
                    gap: "4px",
                    background: "rgba(16, 185, 129, 0.1)",
                    color: "var(--emerald)",
                    fontSize: "11px",
                    fontWeight: 600,
                    padding: "2px 8px",
                    borderRadius: "12px",
                    border: "1px solid rgba(16, 185, 129, 0.2)",
                  }}
                >
                  <CheckCircle2 size={11} /> Solved
                </span>
              )}
            </div>
            <h2>{activePuzzle.title}</h2>
          </div>

          <div className="problem-scenario">
            <strong>Scenario:</strong> {activePuzzle.businessScenario}
          </div>

          <div className="problem-prompt-box">
            <p>
              <strong>Your Task:</strong> Debug the following query. It has a
              logical flaw or syntax error.
            </p>
            <pre className="sql-pre">{activePuzzle.flawedQuery}</pre>
          </div>

          <div
            className="hint-card"
            style={{
              marginTop: "16px",
              background: "rgba(245, 158, 11, 0.05)",
              border: "1px solid rgba(245, 158, 11, 0.15)",
              borderRadius: "6px",
              padding: "10px 14px",
              display: "flex",
              alignItems: "flex-start",
              gap: "8px",
            }}
          >
            <Lightbulb
              size={14}
              style={{ marginTop: "2px", color: "var(--amber)", flexShrink: 0 }}
            />
            <div style={{ fontSize: "12.5px", color: "var(--text)" }}>
              <strong>Hint:</strong> {activePuzzle.hint}
            </div>
          </div>

          <div className="hint-actions" style={{ marginTop: "24px" }}>
            <button
              className="primary-button"
              onClick={() => openPuzzleInPlayground(activePuzzle)}
            >
              <Bug size={14} /> Debug in Playground
            </button>
            <button
              className="icon-button labeled"
              onClick={() => setSolutionRevealed((r) => !r)}
            >
              <Sparkles size={14} />{" "}
              {solutionRevealed ? "Hide Solution" : "Reveal Solution"}
            </button>
            {progress.solvedPuzzles?.includes(activePuzzle.id) && (
              <span
                style={{
                  fontSize: "12px",
                  color: "var(--emerald)",
                  fontWeight: "bold",
                  display: "inline-flex",
                  alignItems: "center",
                  gap: "4px",
                }}
              >
                <CheckCircle2 size={14} /> Solved ✓
              </span>
            )}
          </div>

          {solutionRevealed && (
            <div
              className="solution-card animate-fade-in"
              style={{ marginTop: "20px" }}
            >
              <h3>Correct Solution</h3>
              <pre className="sql-pre">{activePuzzle.solutionQuery}</pre>
              <p style={{ marginTop: "12px" }}>
                <strong>The Mistake:</strong> {activePuzzle.mistakeExplanation}
              </p>
              <button
                className="icon-button labeled"
                style={{ marginTop: "8px" }}
                onClick={() => {
                  setPlaygroundMode("puzzle");
                  updateEditorQuery(activePuzzle.solutionQuery);
                  setActiveView("playground");
                }}
              >
                <Play size={14} /> Load Solution in Playground
              </button>
            </div>
          )}
        </div>
      }
    />
  );
}

export default React.memo(PuzzlesView);

import { setStorageItem } from "../../utils/storage";
import React, { useState, useRef } from "react";
import MockTestView from "./MockTestView";
import { useProgress } from "../../contexts/ProgressContext";
import { useCurriculum } from "../../contexts/CurriculumContext";
import { useV3Dispatch } from "../../contexts/V3Store";
import { mockInterviews, interviewQuestionBank } from "../../data/curriculum";
import { runQuery } from "../../utils/sqlEngine";
import { gradeQuery } from "../../utils/graderService";
import { useLocalStorage } from "../../hooks/useLocalStorage";

export default function V2MockTestBridge() {
  const { progress, setProgress } = useProgress();
  const { allProblems } = useCurriculum();
  const dispatch = useV3Dispatch();

  // Local state for mock test runner
  const [activeSubView, setActiveSubView] = useState<
    "mocks" | "mock-runner" | "mock-results"
  >("mocks");
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [mockTest, setMockTest] = useState<any | null>(null);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [mockReviewIndex, setMockReviewIndex] = useState(0);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [mockHistory, setMockHistory] = useLocalStorage<any[]>(
    "sql-aa-mock-history",
    [],
  );

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [query, setQuery] = useState("");
  const queryRef = useRef("");
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [queryResult, setQueryResult] = useState<any>({
    columns: [],
    rows: [],
    message: "",
  });
  const [resultPage, setResultPage] = useState(1);

  // Editor settings via useLocalStorage
  const [sqlUpperKeywords, setSqlUpperKeywords] = useLocalStorage(
    "sql-aa-upper-keywords",
    true,
  );
  const [editorFontSize, setEditorFontSize] = useLocalStorage(
    "sql-aa-font-size",
    14,
  );
  const [editorWordWrap, setEditorWordWrap] = useLocalStorage(
    "sql-aa-word-wrap",
    false,
  );
  const [editorMinimap, setEditorMinimap] = useLocalStorage(
    "sql-aa-minimap",
    false,
  );
  const [editorFontFamily, setEditorFontFamily] = useLocalStorage(
    "sql-aa-font-family",
    "Fira Code",
  );
  const [editorTabSize, setEditorTabSize] = useLocalStorage(
    "sql-aa-tab-size",
    2,
  );
  const [editorTheme, setEditorTheme] = useLocalStorage(
    "sql-aa-theme",
    "vs-dark",
  );

  const startMockTest = (
    company: string,
    minutes: number,
    diff: string,
    maxMod: number,
    qCount: number,
  ) => {
    const diffMap: Record<string, string[]> = {
      Beginner: ["Easy"],
      "Beginner → Intermediate": ["Easy", "Medium"],
      Intermediate: ["Medium"],
      "Intermediate → Advanced": ["Medium", "Hard"],
      Advanced: ["Hard"],
    };
    const allowedDifficulties = diffMap[diff] || ["Easy", "Medium", "Hard"];

    const failedMap = JSON.parse(
      localStorage.getItem("sql-aa-failed-attempts") || "{}",
    );
    const candidates = allProblems.filter(
      (p) => p.moduleId <= maxMod && allowedDifficulties.includes(p.difficulty),
    );

    const problems = candidates
      .map((p) => ({
        problem: p,
        weight:
          (failedMap[p.id] || 0) +
          (progress.solvedProblems.includes(p.id) ? 0.1 : 1.0) *
            (Math.random() + 0.5),
      }))
      .sort((a, b) => b.weight - a.weight)
      .map((x) => x.problem)
      .slice(0, qCount);

    const finalProblems =
      problems.length === qCount
        ? problems
        : candidates.sort(() => 0.5 - Math.random()).slice(0, qCount);

    setMockTest({
      company,
      questions: finalProblems,
      currentIndex: 0,
      answers: [],
      timeRemaining: minutes * 60,
      isActive: true,
    });
    setQuery("");
    queryRef.current = "";
    setQueryResult({ columns: [], rows: [], message: "" });
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    setActiveSubView("mock-runner");
  };

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const finishMockTest = (finalState: any) => {
    finalState.isActive = false;
    setMockTest(finalState);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    setActiveSubView("mock-results");
    setMockReviewIndex(0);

    const score = Math.round(
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      (finalState.answers.filter((a: any) => a.isCorrect).length /
        finalState.questions.length) *
        100,
    );

    const histEntry = {
      id: Date.now().toString(),
      date: new Date().toISOString(),
      company: finalState.company,
      score,
      timeSpent: finalState.timeRemaining, // V2 logic assumed time remaining tracking was handled elsewhere, we'll store raw score
    };
    setMockHistory([histEntry, ...mockHistory]);

    // Update global progress context with mock score
    setProgress({
      ...progress,
      mockScores: {
        ...progress.mockScores,
        [histEntry.id]: score,
      },
    });
// eslint-disable-next-line @typescript-eslint/no-explicit-any

    // Update failed attempts
    const failedMap = JSON.parse(
      localStorage.getItem("sql-aa-failed-attempts") || "{}",
    );
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    finalState.answers.forEach((ans: any, idx: number) => {
      const q = finalState.questions[idx];
      if (!ans.isCorrect) {
        failedMap[q.id] = (failedMap[q.id] || 0) + 1;
      }
    });
    setStorageItem("sql-aa-failed-attempts", JSON.stringify(failedMap));
  };

  const submitMockAnswer = async (sql: string) => {
    if (!mockTest) return;
    const currentQ = mockTest.questions[mockTest.currentIndex];

    try {
      const userRes = await runQuery(sql);
      const expectedRes = await runQuery(currentQ.solution);

      const graderRes = gradeQuery({
        userQuery: sql,
        solutionSql: currentQ.solution,
        userResult: userRes,
        expectedResult: expectedRes,
        userSnapshot: null,
        expectedSnapshot: null,
        playgroundMode: "practice",
      });

      const newAnswers = [
        ...mockTest.answers,
        { query: sql, isCorrect: graderRes.isCorrect },
      ];

      if (mockTest.currentIndex === mockTest.questions.length - 1) {
        finishMockTest({ ...mockTest, answers: newAnswers });
      } else {
        setMockTest({
          ...mockTest,
          answers: newAnswers,
          currentIndex: mockTest.currentIndex + 1,
        });
        setQuery("");
        queryRef.current = "";
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        setQueryResult({
          columns: [],
          rows: [],
          message: "Run your query to test it.",
        });
      }
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    } catch (e: any) {
      setQueryResult({ columns: [], rows: [], message: "", error: e.message });
    }
  };

  const runCurrentQuery = async () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    try {
      const res = await runQuery(query);
      setQueryResult({
        columns: res.columns || [],
        rows: res.rows || [],
        message: "Success",
      });
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    } catch (e: any) {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      setQueryResult({ columns: [], rows: [], message: "", error: e.message });
    }
  };

  return (
    <MockTestView
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      {...({} as any)}
      activeView={activeSubView}
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      setActiveView={(v: any) => {
        if (v === "mocks" || v === "mock-runner" || v === "mock-results") {
          setActiveSubView(v);
        } else {
          dispatch({ type: "SET_VIEW", payload: v });
        }
      }}
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      progress={progress as any}
      mockInterviews={mockInterviews}
      mockHistory={mockHistory}
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      interviewQuestionBank={allProblems as any}
      mockTest={mockTest}
      setMockTest={setMockTest}
      mockReviewIndex={mockReviewIndex}
      setMockReviewIndex={setMockReviewIndex}
      startMockTest={startMockTest}
      submitMockAnswer={submitMockAnswer}
      runCurrentQuery={runCurrentQuery}
      queryRef={queryRef}
      queryResult={queryResult}
      resultPage={resultPage}
      setResultPage={setResultPage}
      RESULT_PAGE_SIZE={10}
      updateEditorQuery={(sql) => {
        setQuery(sql);
        queryRef.current = sql;
      }}
      editorTheme={editorTheme}
      theme="dark"
      query={query}
      handleBeforeMount={() => {}}
      handleMount={() => {}}
      handleEditorChange={(val) => {
        setQuery(val || "");
        queryRef.current = val || "";
      }}
      editorFontSize={editorFontSize}
      editorWordWrap={editorWordWrap}
      editorMinimap={editorMinimap}
      editorFontFamily={editorFontFamily}
      editorTabSize={editorTabSize}
    />
  );
}

import React, { useState, useMemo, useEffect } from "react";
import PlaygroundView from "./PlaygroundView";
import { debugPuzzles } from "../../data/puzzles";
import { useProgress } from "../../contexts/ProgressContext";
import { useCurriculum } from "../../contexts/CurriculumContext";
import { useV3State, useV3Dispatch } from "../../contexts/V3Store";
import { runQuery, QueryResult } from "../../utils/sqlEngine";
import { tableSchemas, datasetDomains } from "../../data/datasets";
import { gradeQuery } from "../../utils/graderService";
import { useLocalStorage } from "../../hooks/useLocalStorage";

export default function V2PlaygroundBridge() {
  const { progress, setProgress } = useProgress();
  const { roadmapModules, allProblems } = useCurriculum();
  const { activeView, playgroundMode, activeProblemId } = useV3State();
  const dispatch = useV3Dispatch();

  // Local state for the playground editor settings via useLocalStorage
  const [rowLimit, setRowLimit] = useLocalStorage("sql-aa-row-limit", "100");
  const [sqlUpperKeywords, setSqlUpperKeywords] = useLocalStorage(
    "sql-aa-upper-keywords",
    true,
  );
  const [editorFontSize, setEditorFontSize] = useLocalStorage(
    "sql-aa-font-size",
    14,
  );
  const [editorWordWrap, setEditorWordWrap] = useLocalStorage(
    "sql-aa-word-wrap",
    false,
  );
  const [editorMinimap, setEditorMinimap] = useLocalStorage(
    "sql-aa-minimap",
    false,
  );
  const [editorFontFamily, setEditorFontFamily] = useLocalStorage(
    "sql-aa-font-family",
    "Fira Code",
  );
  const [editorTabSize, setEditorTabSize] = useLocalStorage(
    "sql-aa-tab-size",
    2,
  );
  const [editorTheme, setEditorTheme] = useLocalStorage(
    "sql-aa-theme",
    "vs-dark",
  );

  const [query, setQuery] = useState("");
  const [queryResult, setQueryResult] = useState<QueryResult>({
    columns: [],
    rows: [],
    message: "",
  });
  const [expectedResult, setExpectedResult] = useState<QueryResult | null>(
    null,
  );
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [graderFeedback, setGraderFeedback] = useState<any>(null);

  const activeProblem = useMemo(() => {
    if (playgroundMode === "practice") {
      return allProblems.find((p) => p.id === activeProblemId) || null;
    } else if (playgroundMode === "puzzle") {
      return debugPuzzles.find((p) => p.id === activeProblemId) || null;
    }
    return null;
  }, [allProblems, playgroundMode, activeProblemId]);

  useEffect(() => {
    if (activeProblem && playgroundMode === "practice") {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      setQuery(
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        (activeProblem as any).starterCode ||
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          (activeProblem as any).starterQuery ||
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          "",
      );
    } else if (activeProblem && playgroundMode === "puzzle") {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      setQuery((activeProblem as any).flawedQuery || "");
    } else {
      setQuery("");
    }
    setQueryResult({ columns: [], rows: [], message: "" });
    setExpectedResult(null);
    setGraderFeedback(null);
  }, [activeProblem, playgroundMode]);

  const handleRunQuery = async () => {
    try {
      const res = await runQuery(query);
      setQueryResult(res);
      setExpectedResult(null);
      setGraderFeedback(null);

      if (
        activeProblem &&
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        (playgroundMode === "practice" || playgroundMode === "puzzle")
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      ) {
        const solutionSql =
          playgroundMode === "practice"
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            ? (activeProblem as any).solution
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            : (activeProblem as any).solutionQuery;

        if (solutionSql) {
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          const expectedRes = await runQuery(solutionSql);
          setExpectedResult(expectedRes);

          const isFlawedQueryUnchanged =
            playgroundMode === "puzzle"
              ? query.trim().toLowerCase() ===
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                (activeProblem as any).flawedQuery?.trim().toLowerCase()
              : false;

          const graderRes = gradeQuery({
            userQuery: query,
            solutionSql,
            userResult: res,
            expectedResult: expectedRes,
            userSnapshot: null,
            expectedSnapshot: null,
            playgroundMode: playgroundMode,
            isFlawedQueryUnchanged,
          });

          setGraderFeedback(graderRes);

          if (graderRes.isCorrect) {
            if (playgroundMode === "practice") {
              if (!progress.solvedProblems.includes(activeProblem.id)) {
                setProgress({
                  ...progress,
                  solvedProblems: [
                    ...progress.solvedProblems,
                    activeProblem.id,
                  ],
                });
              }
            } else if (playgroundMode === "puzzle") {
              if (!progress.solvedPuzzles?.includes(activeProblem.id)) {
                setProgress({
                  ...progress,
                  solvedPuzzles: [
                    ...(progress.solvedPuzzles || []),
                    activeProblem.id,
                  // eslint-disable-next-line @typescript-eslint/no-explicit-any
                  ],
                });
              }
            }
          }
        }
      }
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    } catch (e: any) {
      setQueryResult({
        columns: [],
        rows: [],
        message: "",
        error: e.message || "Error running query",
      });
    }
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  };

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const copyToClipboard = (text: string) => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    navigator.clipboard.writeText(text);
  };

  return (
    <PlaygroundView
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      {...({} as any)}
      progress={progress}
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      selectedProblem={activeProblem as any}
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      playgroundMode={playgroundMode as any}
      setPlaygroundMode={(mode: "practice" | "puzzle" | "free") =>
        dispatch({ type: "SET_PLAYGROUND_MODE", payload: mode })
      }
      roadmapModules={roadmapModules}
      tableSchemas={tableSchemas}
      datasetDomains={datasetDomains}
      rowLimit={rowLimit}
      setRowLimit={setRowLimit}
      sqlUpperKeywords={sqlUpperKeywords}
      setSqlUpperKeywords={setSqlUpperKeywords}
      editorFontSize={editorFontSize}
      setEditorFontSize={setEditorFontSize}
      editorWordWrap={editorWordWrap}
      setEditorWordWrap={setEditorWordWrap}
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      editorMinimap={editorMinimap}
      setEditorMinimap={setEditorMinimap}
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      editorFontFamily={editorFontFamily}
      setEditorFontFamily={setEditorFontFamily}
      editorTabSize={editorTabSize}
      setEditorTabSize={setEditorTabSize}
      editorTheme={editorTheme}
      setEditorTheme={setEditorTheme}
      theme="dark"
      query={query}
      setQuery={setQuery}
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      queryResult={queryResult as any}
      setQueryResult={setQueryResult}
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      expectedResult={expectedResult as any}
      setExpectedResult={setExpectedResult}
      graderFeedback={graderFeedback}
      setGraderFeedback={setGraderFeedback}
      runCurrentQuery={handleRunQuery}
      copyToClipboard={copyToClipboard}
      allProblems={allProblems}
      liveSchema={[]}
      setLiveSchema={() => {}}
      savedQueries={[]}
      setSavedQueries={() => {}}
      debugPuzzles={debugPuzzles}
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      activePuzzle={activeProblem as any}
      setActivePuzzleId={(id: string) =>
        dispatch({ type: "SET_PROBLEM", payload: id })
      }
      getSavedPuzzleQuery={() => ""}
      getSavedDraftQuery={() => ""}
      updateEditorQuery={(val: string) => setQuery(val)}
      stopAutoTyping={() => {}}
      editorRef={{ current: null }}
      queryRef={{ current: query }}
      showToast={() => {}}
      showConfirm={() => {}}
      showPrompt={() => {}}
      graderStrict={false}
      setGraderStrict={() => {}}
      learningRoadmap={[]}
      readiness={100}
      totalModules={roadmapModules.length}
      totalProblems={allProblems.length}
    />
  );
}

import React from "react";
import PracticeView from "./PracticeView";
import { useProgress } from "../../contexts/ProgressContext";
import { useCurriculum } from "../../contexts/CurriculumContext";
import { useV3Dispatch, useV3State } from "../../contexts/V3Store";

export default function V2PracticeBridge() {
  const { progress, setProgress } = useProgress();
  const { roadmapModules } = useCurriculum();
  const { activeProblemId, activeModuleId: v3ModuleId } = useV3State();
  const dispatch = useV3Dispatch();

  const activeModuleId = v3ModuleId || 1;
  const activeModule =
    roadmapModules.find((m) => m.id === activeModuleId) || roadmapModules[0];
  const selectedProblem =
    activeModule.problems.find((p) => p.id === activeProblemId) ||
    activeModule.problems[0];

  const classForDiff = (d: string) => {
    const lower = (d || "").toLowerCase();
    if (lower.includes("expert")) return "expert";
    if (lower.includes("advanced") || lower.includes("hard")) return "hard";
    if (lower.includes("intermediate") || lower.includes("medium"))
      return "medium";
    return "easy";
  };

  return (
    <PracticeView
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      {...({} as any)}
      progress={progress}
      activeModuleId={activeModuleId}
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      roadmapModules={roadmapModules}
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      selectedProblem={selectedProblem as any}
      selectProblem={(p) => {
        dispatch({ type: "SET_PROBLEM", payload: p.id });
      }}
      openInPlayground={(p) => {
        dispatch({ type: "SET_PROBLEM", payload: p.id });
        dispatch({ type: "SET_VIEW", payload: "playground" });
      }}
      markProblemSolved={(p, quality) => {
        setProgress((prev) => {
          if (!prev.solvedProblems.includes(p.id)) {
            return { ...prev, solvedProblems: [...prev.solvedProblems, p.id] };
          }
          return prev;
        });
      }}
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      updateEditorQuery={() => {}}
      copyToClipboard={(text) => navigator.clipboard.writeText(text)}
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      classForDiff={classForDiff as any}
      selectModule={(m) => {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        dispatch({ type: "SET_DAY", payload: m.id });
      }}
      setActiveView={(view) =>
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        dispatch({ type: "SET_VIEW", payload: view as any })
      }
      setPlaygroundMode={(mode) =>
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        dispatch({ type: "SET_PLAYGROUND_MODE", payload: mode as any })
      }
    />
  );
}

import React from "react";
import RoadmapView from "./RoadmapView";
import { useProgress } from "../../contexts/ProgressContext";
import { useCurriculum } from "../../contexts/CurriculumContext";
import { useV3Dispatch } from "../../contexts/V3Store";
import { debugPuzzles } from "../../data/puzzles";
import type { ViewId, PlaygroundMode } from "../../types";

export default function V2RoadmapBridge() {
  const { progress, setProgress } = useProgress();
  const { learningRoadmap, roadmapModules } = useCurriculum();
  const dispatch = useV3Dispatch();

  return (
    <RoadmapView
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      {...({} as any)}
      progress={progress}
      learningRoadmap={learningRoadmap}
      roadmapModules={roadmapModules}
      setSelectedDayId={(dayId: number) =>
        dispatch({ type: "SET_DAY", payload: dayId })
      }
      setActiveView={(view: ViewId) =>
        dispatch({ type: "SET_VIEW", payload: view })
      }
      toggleDayComplete={(day: number) => {
        setProgress((prev) => {
          if (prev.completedDays.includes(day)) {
            return {
              ...prev,
              completedDays: prev.completedDays.filter((d) => d !== day),
            };
          }
          return { ...prev, completedDays: [...prev.completedDays, day] };
        });
      }}
      selectModule={(m) => {
        dispatch({ type: "SET_DAY", payload: m.id });
        dispatch({ type: "SET_VIEW", payload: "interactive-lesson" });
      }}
      openInPlayground={(p) => {
        // Mock behavior for V3
        dispatch({ type: "SET_VIEW", payload: "playground" });
      }}
      debugPuzzles={debugPuzzles}
      setActivePuzzleId={(id: string) => {
        // Map to playground or puzzles
        dispatch({ type: "SET_VIEW", payload: "puzzles" });
      }}
      setPlaygroundMode={(mode: "practice" | "puzzle" | "free") => {}}
      getSavedPuzzleQuery={(p) => ""}
      updateEditorQuery={(newVal, pMode, targetId, moveCursorToEnd) => {}}
      stopAutoTyping={() => {}}
    />
  );
}
